window.GERIA = {"temas": [{"n": 1, "titulo": "Fisiología y farmacología del envejecimiento", "items": [{"id": "g2-21", "q": "¿Cuál de las siguientes estrategias hubiera sido adecuada?", "x": 2, "o": ["Retirar el medicamento paulatinamente", "Duplicar la dosis", "Cambiar por un anticolinérgico", "Suspenderlo súbitamente"], "k": 0, "a": "Retirar el medicamento paulatinamente", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 2, diapo 13) — Desprescripción: «¿Requiere reducción gradual (tapering)?… La desprescripción gradual minimiza el riesgo de síndromes de abstinencia o rebote».", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g2-c1"}, {"id": "g2-22", "q": "¿Cuál factor de riesgo para reacciones adversas estaba presente en este paciente?", "x": 2, "o": ["Uso de paracetamol", "Sexo masculino", "Cuidado de salud fraccionado (varios médicos)", "Hiperplasia prostática asintomática"], "k": 2, "a": "Cuidado de salud fraccionado (varios médicos)", "w": "No viene en tus documentos — Se dejó la clave del examen.", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g2-c1"}, {"id": "g2-23", "q": "El manejo farmacológico del adulto mayor muestra cambios asociados al envejecimiento de órganos y mecanismos homeostáticos. Señale el enunciado correcto:", "x": 3, "o": ["La concentración plasmática de los hidrofílicos disminuye", "La vida media de los fármacos lipofílicos disminuye", "El volumen de distribución de las sustancias lipofílicas está disminuido", "El volumen de distribución de las sustancias hidrofílicas está disminuido por la menor cantidad de agua corporal"], "k": 3, "a": "El volumen de distribución de las sustancias hidrofílicas está disminuido por la menor cantidad de agua corporal", "w": "Confirmado en Andy Notas ✔ (p. 16) — Hidrofílicos: Vd disminuye y la misma dosis da concentraciones más altas; lipofílicos: Vd aumenta (Bairo p. 25).", "nt": "Nota: En Nov 2025 la clave recordada decía \"lipofílicas disminuido\", pero el propio alumno anotó que era \"aumentado\".", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-24", "q": "Es uno de los cambios fisiológicos del envejecimiento:", "x": 3, "o": ["Aumenta la masa magra", "El gasto energético total disminuye con la edad", "La sensibilidad a la insulina mejora", "El metabolismo basal aumenta"], "k": 1, "a": "El gasto energético total disminuye con la edad", "w": "Confirmado en Andy Notas ✔ (p. 15) — Disminuye por menor actividad física y menor gasto en reposo.", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-25", "q": "En relación a los cambios del volumen de distribución de los fármacos con la edad, señale el enunciado correcto:", "x": 2, "o": ["Disminuye la vida media de las sustancias liposolubles", "Aumenta la concentración plasmática de las sustancias hidrosolubles", "Aumenta el volumen de distribución de las sustancias hidrosolubles", "Disminuye el volumen de distribución de las sustancias liposolubles"], "k": 1, "a": "Aumenta la concentración plasmática de las sustancias hidrosolubles", "w": "Confirmado en Andy Notas ✔ (p. 16)", "f": "Ago-Dic 2020 (+ otra clave), Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g2-26", "q": "Son cambios fisiológicos en la piel por el envejecimiento:", "x": 2, "o": ["El estrato córneo se adelgaza de forma importante", "Aumenta la producción de melanocitos", "Aumenta la vascularidad dérmica", "El grosor de la epidermis disminuye levemente y el estrato córneo permanece sin cambios"], "k": 3, "a": "El grosor de la epidermis disminuye levemente y el estrato córneo permanece sin cambios", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 3, diapo 6) — «Grosor de epidermis disminuye levemente y no ocurre en el estrato córneo… los componentes del estrato córneo se mantienen por más tiempo». También en Andy Notas (p. 11).", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-27", "q": "Son cambios fisiológicos del envejecimiento ocular:", "x": 2, "o": ["Aumento de la secreción lagrimal", "Aumento del diámetro pupilar", "Mejoría de la acomodación", "Rigidez corneal y astigmatismo inverso"], "k": 3, "a": "Rigidez corneal y astigmatismo inverso", "w": "No viene en tus documentos — Andy p. 13 describe arco senil y atrofia lagrimal, pero no la rigidez corneal ni el astigmatismo inverso.", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-28", "q": "Entre los cambios fisiológicos homeostáticos que intervienen en la respuesta adversa a medicamentos, ¿cuál representa una alteración del sistema nervioso autónomo?", "x": 3, "o": ["Delirium", "Insuficiencia renal", "Hipoglucemia", "Ortostatismo"], "k": 3, "a": "Ortostatismo", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 3, diapo 19) — «Hipotensión ortostática por cambios en reflejos barorreceptores»; Tema 2, diapo 12: síncope por prazosina + metoprolol por «pérdida natural del reflejo de los barorreceptores». También en Andy Notas (p. 42).", "r": 1, "f": "Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-29", "q": "¿Cuál de los siguientes enunciados está entre los principios de la farmacoterapia geriátrica?", "x": 3, "o": ["Los antibióticos no son riesgo de reacciones adversas", "El manejo farmacológico es prioritario en los síndromes geriátricos", "Revise apego, simplifique el régimen y considere el uso de agendas o recordatorios", "Se considera polifarmacia al uso de dos medicamentos en cualquier situación"], "k": 2, "a": "Revise apego, simplifique el régimen y considere el uso de agendas o recordatorios", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 2, diapo 14) — «REVIEW OFTEN: revisión exhaustiva de la bolsa de los medicamentos en cada consulta»; «START LOW: iniciar siempre con la dosis efectiva más baja posible». También en BAIRONOTAS (p. 27).", "r": 1, "f": "Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-30", "q": "Referente a los cambios en la composición corporal en la vejez que pueden influir en la farmacocinética, señale lo correcto:", "x": 1, "o": ["Aumento de la masa magra total", "Aumento del tejido graso total", "Aumento del tamaño renal y hepático", "Aumento del tamaño corporal total"], "k": 1, "a": "Aumento del tejido graso total", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 3, diapo 5) — «Tejido adiposo: aumenta en la edad adulta… acumulación en las vísceras y tejido subcutáneo abdominal»; la masa magra «disminuye durante toda la vida adulta» (diapo 4). También en Andy Notas (p. 11).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g2-31", "q": "Aseveración correcta respecto a la farmacocinética asociada al envejecimiento que afecta al metabolismo de los medicamentos:", "x": 1, "o": ["Aumento de la fase 1", "Ambas fases se encuentran aumentadas", "Ligera disminución de la fase 1 (oxidación, reducción, hidrólisis por citocromo) con fase 2 (glucuronidación, acetilación) preservada", "Disminución importante de la fase 2"], "k": 2, "a": "Ligera disminución de la fase 1 (oxidación, reducción, hidrólisis por citocromo) con fase 2 (glucuronidación, acetilación) preservada", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 2, diapo 3) — «Fase I (oxidación/reducción): disminuida. Cae la actividad del CyP-450… Fase II (conjugación/glucuronidación): preservada». También en BAIRONOTAS (p. 26).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-32", "q": "Identifique los fenómenos asociados a trastornos del sistema nervioso autónomo considerados cambios de la edad:", "x": 1, "o": ["Disminución de la masa muscular y trastorno de la estabilidad postural", "Ortostatismo y trastorno funcional vesical o intestinal", "Disminución de la reserva cognitiva", "Ingesta disminuida e intolerancia a la glucosa"], "k": 1, "a": "Ortostatismo y trastorno funcional vesical o intestinal", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 3, diapo 19) — «Hipotensión ortostática por cambios en reflejos barorreceptores»; en la vejiga «aumenta el número de contracciones desinhibidas… el volumen residual aumenta» (diapo 25). También en Andy Notas (p. 42).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g2-33", "q": "Cambio en el sentido del gusto con el envejecimiento:", "x": 1, "o": ["Ningún cambio", "Mejora del gusto", "Solo cambia el olfato", "Todas las opciones se dieron como correctas (aumento del umbral de reconocimiento de sabores)"], "k": 3, "a": "Todas las opciones se dieron como correctas (aumento del umbral de reconocimiento de sabores)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 3, diapo 15) — «Disminuye la capacidad para distinguir sabores; asociado a disminución en la capacidad del olfato». También en BAIRONOTAS (p. 20).", "r": 1, "f": "Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g2-34", "q": "Con la edad aumenta la grasa corporal. ¿Qué consecuencia tiene sobre los fármacos lipofílicos?", "x": 1, "o": ["No cambia su farmacocinética", "Disminuye su volumen de distribución", "Aumenta su volumen de distribución (y prolonga su vida media)", "Disminuye su vida media"], "k": 2, "a": "Aumenta su volumen de distribución (y prolonga su vida media)", "w": "Confirmado en Andy Notas con matiz (p. 16) — Los alumnos recordaron \"aumenta la biodisponibilidad\"; Andy lo explica como aumento del Vd y de la vida media.", "r": 1, "f": "2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}]}, {"n": 2, "titulo": "Envejecimiento, geriatría y gerontología / Demografía y propedéutica", "items": [{"id": "g1-1", "q": "Con base en el envejecimiento poblacional y las recomendaciones de la ONU, ¿cómo se considera a la población estudiada?", "x": 1, "o": ["Población vulnerable", "Población dependiente", "Población geriátrica", "Población envejecida"], "k": 3, "a": "Población envejecida", "w": "Confirmado en Andy Notas ✔ (p. 4) — La población se considera envejecida cuando los adultos mayores pasan del 10 % (Bairo p. 6).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g1-c1"}, {"id": "g1-2", "q": "¿Cómo se define la tasa de dependencia?", "x": 1, "o": ["Relación entre la población económicamente activa y los dependientes mayores de 65 años, sin considerar a los menores", "Relación entre la población en edad activa y los dependientes, considerando a los menores de 14 y mayores de 65 años", "Relación entre la población económicamente activa y los dependientes, considerando a los menores de 14 y mayores de 65 años", "Relación entre la población inactiva y la activa, independientemente de la edad"], "k": 1, "a": "Relación entre la población en edad activa y los dependientes, considerando a los menores de 14 y mayores de 65 años", "w": "Confirmado en BAIRONOTAS con matiz (p. 7) — Clave del alumno en la versión resuelta de Ene-Jun 2020. Bairo describe la tasa de dependencia como cuántas personas activas sostienen a una dependiente.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g1-c1"}, {"id": "g1-3", "q": "¿Cómo se define y se caracteriza el fenómeno del envejecimiento poblacional?", "x": 1, "o": ["Aumento en el número y proporción de adultos mayores, con mayor vulnerabilidad social y económica, alto grado de discapacidad y predominio femenino", "Aumento de la población geriátrica que requiere mayor cuidado de salud y atención domiciliaria", "Aumento de adultos mayores nacidos entre 1955 y 1980 que generan una ola generacional con discapacidad y muerte prematura", "Disminución de la natalidad con menor proporción de cuidadores potenciales"], "k": 0, "a": "Aumento en el número y proporción de adultos mayores, con mayor vulnerabilidad social y económica, alto grado de discapacidad y predominio femenino", "w": "Confirmado en BAIRONOTAS con matiz (p. 5) — Definición: \"dramático incremento en el número y proporción de adultos mayores\"; la discapacidad es predominantemente femenina (Bairo p. 8). El examen no traía clave.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g1-c1"}, {"id": "g1-4", "q": "Señale los factores demográficos que han provocado el envejecimiento poblacional:", "x": 5, "o": ["Migración, aumento de fertilidad y aumento de mortalidad", "Migración, disminución de mortalidad y disminución de natalidad", "Aumento de mortalidad y disminución de natalidad", "Índice de envejecimiento, longevidad y migración"], "k": 1, "a": "Migración, disminución de mortalidad y disminución de natalidad", "w": "Confirmado en BAIRONOTAS ✔ (p. 29) — Determinantes: natalidad, mortalidad y migración (Andy p. 4).", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos), Ene-Jun 2015, Examen 2012"}, {"id": "g1-5", "q": "En relación al envejecimiento exitoso, señale el enunciado correcto:", "x": 5, "o": ["Se trata de un argumento de origen cultural favorecido por el prejuicio asociado a la edad", "Está determinado por factores genéticos asociados a protección contra el proceso oxidativo", "Distinguir entre envejecimiento y enfermedad se logra con marcadores genéticos presentes en marcadores tumorales", "Afirmar que un entorno y un estilo de vida llevan a un envejecimiento exitoso es aún arriesgado"], "k": 3, "a": "Afirmar que un entorno y un estilo de vida llevan a un envejecimiento exitoso es aún arriesgado", "w": "No viene en tus documentos — Andy p. 11 solo define el envejecimiento exitoso como \"pocos cambios aparentes\"; la frase de la clave no viene en tus documentos.", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g1-6", "q": "En relación al envejecimiento, señale el enunciado correcto:", "x": 3, "o": ["El envejecimiento está programado genéticamente", "El envejecimiento es la suma de las enfermedades del mismo", "El proceso biológico del envejecimiento varía entre tejidos y organismos", "El envejecimiento es lineal y factores aleatorios influyen directamente"], "k": 2, "a": "El proceso biológico del envejecimiento varía entre tejidos y organismos", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 2) — Envejecimiento «Heterogéneo: varía entre personas y entre órganos de una misma persona». También en BAIRONOTAS (p. 3).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g1-7", "q": "Definido como el deterioro que ocurre después de la maduración, que provoca una vulnerabilidad mayor a los retos y disminuye la habilidad del organismo para sobrevivir:", "x": 3, "o": ["Senescencia", "Senilidad", "Envejecimiento", "Vejez"], "k": 0, "a": "Senescencia", "w": "No viene en tus documentos — La definición no viene en tus documentos; se dejó la clave de los exámenes.", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g1-8", "q": "Una de sus características es la disminución de la redundancia fisiológica de los órganos:", "x": 3, "o": ["Senescencia", "Envejecimiento", "Fragilidad", "Dependencia"], "k": 1, "a": "Envejecimiento", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 22) — Homeostenosis: «reducción progresiva de la reserva homeostática; un mismo estrés produce mayor descompensación». También en Andy Notas (p. 3).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g1-9", "q": "¿Cuál es el índice de envejecimiento de una población?", "x": 3, "o": ["La relación numérica entre ancianos y niños (≥65 años / menores de 15 × 100)", "La proporción de mayores de 65 años sobre la población total", "La esperanza de vida al nacer", "La relación entre población activa e inactiva"], "k": 0, "a": "La relación numérica entre ancianos y niños (≥65 años / menores de 15 × 100)", "w": "No viene en tus documentos — No viene definido en tus documentos (Andy p. 4 solo lo menciona). Se dejó la clave de los exámenes (\"relación entre niños y ancianos\").", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-10", "q": "¿Cuáles son los determinantes de la transición demográfica en nuestro país?", "x": 2, "o": ["Natalidad, morbilidad y longevidad", "Fecundidad y esperanza de vida únicamente", "Natalidad, mortalidad y migración", "Migración e industrialización"], "k": 2, "a": "Natalidad, mortalidad y migración", "w": "Confirmado en BAIRONOTAS ✔ (p. 29)", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-11", "q": "¿Qué causas demográficas iniciaron la ola generacional que está provocando el envejecimiento poblacional actual?", "x": 3, "o": ["Aumento de los nacimientos a partir de la posguerra (2.ª Guerra Mundial), con una explosión demográfica que después se frenó con la planificación familiar", "Disminución de la natalidad después de la 2.ª Guerra Mundial (baby boomers), industrialización y mejora de la expectativa de vida", "Incremento progresivo de la expectativa de vida con disminución de la natalidad a partir de 1985", "Aumento de natalidad entre 1945-1960 y planificación familiar desde 1980, que llevó a aumento de la morbimortalidad"], "k": 0, "a": "Aumento de los nacimientos a partir de la posguerra (2.ª Guerra Mundial), con una explosión demográfica que después se frenó con la planificación familiar", "w": "Confirmado en BAIRONOTAS ✔ (p. 28) — El fenómeno inició en 1945 por el aumento poblacional de la posguerra (baby boomers); después bajó la natalidad. En 2012-2013 la respuesta recordada fue \"natalidad de posguerra, industrialización, mejor expectativa de vida y atención sociosanitaria\".", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), Recopilación 26 nov 2013, Examen 2012"}, {"id": "g1-12", "q": "Explicación general del envejecimiento:", "x": 3, "o": ["Disminución de la talla", "Programación exclusivamente genética", "Aumento en la frecuencia de errores asociada a la edad", "Pérdida de la totalidad de las células madre"], "k": 2, "a": "Aumento en la frecuencia de errores asociada a la edad", "w": "Confirmado en Andy Notas ✔ (p. 3)", "r": 1, "f": "Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-13", "q": "Desde el punto de vista del envejecimiento poblacional, se considera envejecida la población que pasa cierto porcentaje de adultos mayores. ¿Cuál es ese porcentaje?", "x": 1, "o": ["10 %", "15 %", "5 %", "20 %"], "k": 0, "a": "10 %", "w": "Confirmado en Andy Notas ✔ (p. 4)", "r": 1, "f": "Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-14", "q": "Desde el punto de vista del envejecimiento poblacional, señale lo correcto:", "x": 1, "o": ["Solo afecta al grupo de mayores de 65 años", "El impacto se observa en todos los grupos de edad, por una redistribución de la pirámide poblacional y un impacto en la tasa de dependencia", "Disminuye la tasa de dependencia", "Es un fenómeno cíclico sin impacto en la estructura poblacional"], "k": 1, "a": "El impacto se observa en todos los grupos de edad, por una redistribución de la pirámide poblacional y un impacto en la tasa de dependencia", "w": "Confirmado en BAIRONOTAS ✔ (p. 5) — \"Impacto: cambios en la estructura poblacional, en el tamaño y proporciones de algunos grupos de edad\".", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-15", "q": "Las características del envejecimiento incluyen:", "x": 1, "o": ["Aumento de la redundancia fisiológica", "Mejoría de la homeostasis", "Disminución de la capacidad de respuesta de los órganos (a estímulos ambientales)", "Menor susceptibilidad a enfermedades"], "k": 2, "a": "Disminución de la capacidad de respuesta de los órganos (a estímulos ambientales)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 2) — Envejecimiento: proceso que «reduce de forma progresiva la capacidad del organismo para adaptarse» (Tema 3, diapo 2: los cambios «son evidentes en periodos de estrés»). También en Andy Notas (p. 3).", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-16", "q": "En cuanto a la heterogeneidad del envejecimiento, señale lo correcto:", "x": 1, "o": ["No existe variabilidad entre individuos", "Solo depende de la edad cronológica", "Todos los órganos envejecen al mismo ritmo", "Se refleja en parámetros como la velocidad de la marcha y la presión arterial sistólica"], "k": 3, "a": "Se refleja en parámetros como la velocidad de la marcha y la presión arterial sistólica", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 2) — «Heterogéneo: varía entre personas y entre órganos de una misma persona». Las diapositivas no mencionan la marcha ni la presión arterial; se dejó la clave.", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-17", "q": "Mujer de 80 años (caso de valoración integral) con soplo, borde hepático palpable, estertores y disminución de la estatura. En la exploración física, ¿cuál hallazgo es normal y no requiere abordaje diagnóstico?", "x": 1, "o": ["La presencia de soplo cardiaco", "La disminución de la estatura", "La palpación del borde hepático", "Los estertores crepitantes"], "k": 1, "a": "La disminución de la estatura", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 3, diapo 4) — «La estatura empieza a disminuir desde aproximadamente los veinte años de edad en mujeres, 25 en hombres», por compresión de los discos y pérdida de hueso vertebral. También en Andy Notas (p. 11).", "f": "26 may 2022 (Examsoft)"}, {"id": "g1-18", "q": "El envejecimiento exitoso se da en adultos mayores libres de enfermedad y con:", "x": 2, "o": ["Bajo riesgo de enfermedad y discapacidad", "Ausencia de medicamentos", "Actividad laboral activa", "Alto nivel socioeconómico"], "k": 0, "a": "Bajo riesgo de enfermedad y discapacidad", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 5) — Exitoso: «pérdidas fisiológicas mínimas frente a adultos jóvenes; función física y cognitiva conservada»; en cambio el usual es «sin enfermedad manifiesta, con mayor riesgo de enfermar». Por eso el exitoso implica bajo riesgo. También en Andy Notas (p. 11).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-19", "q": "El envejecimiento con éxito es, en realidad, solo el resultado de:", "x": 2, "o": ["Envejecer más lentamente", "Una carga genética especial", "Restricción calórica", "Ausencia total de enfermedades"], "k": 0, "a": "Envejecer más lentamente", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 4, diapo 16) — La gráfica «Declino biológico y envejecimiento» muestra que la curva del envejecimiento exitoso cae más lento que la usual y la de enfermedad.", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g1-20", "q": "Paciente con pérdida del 10 % del peso corporal, evaluación geriátrica normal y opacidad del cristalino; a la palpación se encuentra el borde hepático. ¿Qué estaba alterado en la exploración física?", "x": 1, "o": ["La piel delgada", "El borde hepático palpable", "La opacidad del cristalino", "La disminución de la talla"], "k": 1, "a": "El borde hepático palpable", "w": "No viene en tus documentos — Se dejó la clave recordada (la catarata es esperable con la edad).", "r": 1, "f": "Recopilación 26 nov 2013 · opciones reconstruidas (el original no las conservó)"}]}, {"n": 3, "titulo": "Evaluación geriátrica y síndromes geriátricos", "items": [{"id": "g3-35", "q": "¿Cuál de los parámetros indica la evolución de la funcionalidad básica?", "x": 3, "o": ["Lawton-Brody", "Katz", "MMSE", "Time up and go"], "k": 1, "a": "Katz", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 30) — «Actividades básicas (ABVD): autocuidado · Índice de Katz». También en Andy Notas (p. 19).", "f": "Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g3-c1"}, {"id": "g3-36", "q": "¿Cuál de los parámetros indica la evolución de la funcionalidad instrumental?", "x": 3, "o": ["Time up and go", "Katz", "Lawton-Brody", "GDS"], "k": 2, "a": "Lawton-Brody", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 30) — «Actividades instrumentales (AIVD): vida independiente · Escala de Lawton y Brody». También en Andy Notas (p. 19).", "f": "Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g3-c1"}, {"id": "g3-37", "q": "¿Cuál de los parámetros indica la evolución de la marcha?", "x": 3, "o": ["GDS", "Katz", "Time up and go", "MMSE"], "k": 2, "a": "Time up and go", "w": "Confirmado en Andy Notas ✔ (p. 42)", "f": "Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g3-c1"}, {"id": "g3-38", "q": "De acuerdo a la evaluación por clinimetría, ¿cuál es el enunciado correcto?", "x": 1, "o": ["Probable deterioro cognoscitivo leve, afectivo normal, riesgo de caídas y deterioro funcional básico e instrumental", "Probables alteraciones afectivas y de funciones instrumentales, sin riesgo de caídas", "Alteración de las capacidades cognitivas, funcionales básicas e instrumentales", "Probable alteración afectiva y cognitiva, con impacto funcional en capacidades básicas e instrumentales"], "k": 3, "a": "Probable alteración afectiva y cognitiva, con impacto funcional en capacidades básicas e instrumentales", "w": "Confirmado en Escalas en Geriatría ✔ (p. 1) — GDS 7 (>5) = depresión probable; MMSE 24 limítrofe; Katz 4 y Lawton 4 alterados (Escalas en Geriatría).", "f": "26 may 2022 (Examsoft)", "c": "g3-c2"}, {"id": "g3-39", "q": "Laboratorios: Hb 11.5, VCM 89, Cr 1.6, depuración 29 ml/min. ¿Cuál de los siguientes medicamentos es inapropiado para el tratamiento de su padecimiento?", "x": 1, "o": ["Fluoxetina", "Duloxetina", "Escitalopram", "Sertralina"], "k": 1, "a": "Duloxetina", "w": "No viene en tus documentos — Se dejó la clave: la duloxetina se evita con depuración <30 ml/min.", "nt": "Nota: En el original la opción D repetía \"fluoxetina\".", "f": "26 may 2022 (Examsoft)", "c": "g3-c2"}, {"id": "g3-40", "q": "¿Cuál de los medicamentos que toma NO está contribuyendo al estado depresivo?", "x": 1, "o": ["Clonazepam", "Calcio", "Enalapril", "Clorfenamina"], "k": 1, "a": "Calcio", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 8) — Precipitantes de depresión: «polifarmacia, sedantes / anticolinérgicos, corticoides / estimulantes». El calcio no está en la lista. También en Andy Notas (p. 31).", "f": "26 may 2022 (Examsoft)", "c": "g3-c2"}, {"id": "g3-41", "q": "¿Cuál de los siguientes medicamentos conlleva un riesgo significativo de caídas?", "x": 1, "o": ["Clonazepam", "Calcio", "Enalapril", "Clorfenamina"], "k": 0, "a": "Clonazepam", "w": "CORREGIDO según las Diapositivas 2026 (Tema 5, diapo 17) — La clave era clorfenamina. Según la diapositiva, benzodiazepinas = «delirium, caídas, fracturas, deterioro psicomotor», y anticolinérgicos = «confusión, retención urinaria, estreñimiento, visión borrosa». El fármaco de caídas es el clonazepam (Tema 2, diapo 10: caídas por diazepam). También en Andy Notas (p. 42).", "f": "26 may 2022 (Examsoft)", "c": "g3-c2"}, {"id": "g3-42", "q": "¿Cuál de los siguientes medicamentos puede estar contribuyendo o causando las alteraciones cognitivas?", "x": 1, "o": ["Clonazepam", "Calcio", "Enalapril", "Clorfenamina"], "k": 3, "a": "Clorfenamina", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 2, diapo 9) — «Síndrome confusional agudo (delirium) secundario a fármacos. El detonante: clorfeniramina (anticolinérgico de primera generación)». También en BAIRONOTAS (p. 27).", "f": "26 may 2022 (Examsoft)", "c": "g3-c2"}, {"id": "g3-43", "q": "¿Cuál es el diagnóstico sindromático?", "x": 2, "o": ["Envejecimiento normal", "Fragilidad del adulto mayor (debilidad + fatiga + incapacidad)", "Depresión mayor", "Demencia avanzada"], "k": 1, "a": "Fragilidad del adulto mayor (debilidad + fatiga + incapacidad)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 11, diapo 13) — La fragilidad se presenta con «síntomas inespecíficos: fatiga extrema, pérdida de peso inexplicada, infecciones frecuentes», «delirium: alteración aguda ante enfermedad menor» y «discapacidad fluctuante». Y ojo con el comentario del médico: «la fragilidad no debe usarse para negar tratamientos efectivos» (diapo 20). También en Andy Notas (p. 46).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g3-c3"}, {"id": "g3-44", "q": "Conocemos los factores que predisponen al síndrome geriátrico; hay que buscar el precipitante. ¿Cuál sería?", "x": 2, "o": ["La angina estable", "La hipertensión", "La edad", "Infección urinaria con tratamiento incompleto"], "k": 3, "a": "Infección urinaria con tratamiento incompleto", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 27) — Infección urinaria en el adulto mayor: «delirium, caídas o incontinencia de inicio reciente» en lugar de disuria y fiebre. También en Andy Notas (p. 21).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g3-c3"}, {"id": "g3-45", "q": "Tras tratarlo, el paciente se recuperó cognitiva y funcionalmente. Fue víctima de abuso o negligencia social. ¿Cuál fue?", "x": 2, "o": ["Abandono familiar", "Abuso económico", "Maltrato físico", "Ageísmo o viejismo"], "k": 3, "a": "Ageísmo o viejismo", "w": "Confirmado en Andy Notas ✔ (p. 22) — Atribuir el deterioro \"a la edad\" sin buscar la causa es ageísmo.", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g3-c3"}, {"id": "g3-46", "q": "La evaluación geriátrica contempla precisar las capacidades funcionales, incluyendo las actividades básicas de la vida diaria (Katz), las cuales incluyen:", "x": 3, "o": ["Manejo del dinero", "Continencia (también baño, vestido, uso del sanitario, transferencias y alimentación)", "Preparación de alimentos", "Uso del teléfono"], "k": 1, "a": "Continencia (también baño, vestido, uso del sanitario, transferencias y alimentación)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 30) — ABVD: «baño, vestido, uso del sanitario, transferencias, continencia, alimentación». También en Andy Notas (p. 19).", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-47", "q": "Característica de los síndromes geriátricos:", "x": 3, "o": ["Tienen una causa única", "No aumentan la mortalidad", "Deterioran la calidad de vida", "Son fáciles de definir"], "k": 2, "a": "Deterioran la calidad de vida", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 23) — Síndromes geriátricos: condiciones multifactoriales que «se asocian con desenlaces adversos»; Tema 4, diapo 15: son «frecuente origen de incapacidad funcional o social». También en BAIRONOTAS (p. 39).", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-48", "q": "Las siguientes son actividades instrumentales de la vida diaria, excepto:", "x": 2, "o": ["Ir de compras", "Lavar la ropa", "Usar el teléfono", "Vestirse"], "k": 3, "a": "Vestirse", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 30) — Vestido es ABVD; las AIVD son teléfono, compras, preparar alimentos, casa, ropa, transporte, medicamentos y dinero. También en Andy Notas (p. 19).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g3-49", "q": "Escala que valora selectivamente las actividades instrumentales de la vida diaria:", "x": 2, "o": ["Katz", "Barthel", "Tinetti", "Lawton-Brody"], "k": 3, "a": "Lawton-Brody", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 30) — «Actividades instrumentales (AIVD)… Escala de Lawton y Brody». También en Andy Notas (p. 19).", "r": 1, "f": "Ene-Jun 2024 (revisión), 2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-50", "q": "Las actividades básicas de la vida diaria incluyen:", "x": 1, "o": ["Higiene personal (baño)", "Ir de compras", "Uso de transporte", "Manejo de medicamentos"], "k": 0, "a": "Higiene personal (baño)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 30) — ABVD: «baño, vestido, uso del sanitario, transferencias, continencia, alimentación». También en Andy Notas (p. 19).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-51", "q": "La evaluación geriátrica incluye las actividades instrumentales de la vida diaria (AIVD). Señale la opción correcta:", "x": 1, "o": ["Vestirse", "Alimentarse", "Continencia", "Preparación de alimentos (no \"alimentarse\", que es básica)"], "k": 3, "a": "Preparación de alimentos (no \"alimentarse\", que es básica)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 30) — AIVD: «uso del teléfono, compras, preparación de alimentos, cuidado de la casa, lavado de ropa, uso de transporte, manejo de medicamentos, manejo del dinero». Alimentarse es básica. También en Andy Notas (p. 19).", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-52", "q": "Indique lo correcto en relación a la valoración geriátrica integral:", "x": 1, "o": ["Sustituye a la historia clínica", "Solo la realiza el geriatra", "Se aplica únicamente a pacientes hospitalizados", "Su objetivo es proporcionar el mayor grado de independencia"], "k": 3, "a": "Su objetivo es proporcionar el mayor grado de independencia", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 32) — «La geriatría es la rama clínica de la gerontología; su objetivo central es preservar la función y la autonomía». También en Andy Notas (p. 18).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-53", "q": "¿Cuál elemento NO forma parte de la evaluación del MMSE (Minimental)?", "x": 1, "o": ["Juicio", "Orientación", "Memoria (fijación y recuerdo)", "Atención y cálculo"], "k": 0, "a": "Juicio", "w": "Confirmado en Escalas en Geriatría ✔ (p. 1) — El MMSE evalúa orientación, fijación, atención y cálculo, memoria, lenguaje y praxis constructiva, no juicio.", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-54", "q": "Análisis de síntomas y terapéutico multidimensional del adulto mayor. A este proceso se le conoce como:", "x": 2, "o": ["Evaluación (valoración) geriátrica", "Interconsulta", "Escrutinio poblacional", "Historia clínica tradicional"], "k": 0, "a": "Evaluación (valoración) geriátrica", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 4, diapo 5) — «Áreas de atención: física, funcional, mental, socio-familiar» (valoración multidimensional). También en Andy Notas (p. 18).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-55", "q": "Para la puntuación de los 5 ítems de orientación en el tiempo del MMSE la respuesta debe ser exacta; sin embargo, hay rangos de respuesta para:", "x": 2, "o": ["Año y mes", "Día del mes y estación del año", "Día de la semana", "Hora del día"], "k": 1, "a": "Día del mes y estación del año", "w": "No viene en tus documentos — Se dejó la clave del examen.", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-56", "q": "Paciente de 86 años con carrera comercial, olvidos de 18 meses sin repercusión funcional, MMSE 28. En relación a su escolaridad, el resultado del MMSE es:", "x": 2, "o": ["Normal (<24 en escolaridad alta, <21 baja y <18 analfabetas)", "Deterioro leve", "Deterioro moderado", "Demencia"], "k": 0, "a": "Normal (<24 en escolaridad alta, <21 baja y <18 analfabetas)", "w": "Confirmado en Escalas en Geriatría ✔ (p. 1)", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-57", "q": "¿Qué evaluación sirve para el diagnóstico diferencial y la identificación del perfil psicológico de los diferentes tipos de demencia?", "x": 2, "o": ["MMSE", "Evaluación neuropsicológica", "TAC de cráneo", "Escala de Yesavage"], "k": 1, "a": "Evaluación neuropsicológica", "w": "No viene en tus documentos — Se dejó la clave.", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-58", "q": "Los síndromes geriátricos dependen de múltiples contribuidores. ¿Cuáles son sus factores de riesgo?", "x": 2, "o": ["Sexo masculino y escolaridad alta", "Edad extrema, déficit cognitivo, discapacidad e inmovilidad", "Solo la polifarmacia", "Tabaquismo y alcoholismo"], "k": 1, "a": "Edad extrema, déficit cognitivo, discapacidad e inmovilidad", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 23) — «Factores de riesgo compartidos: edad avanzada, deterioro cognitivo previo, deterioro funcional previo, movilidad alterada». También en Andy Notas (p. 21).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g3-59", "q": "En el adulto mayor, ¿cómo suelen presentarse las enfermedades de inicio agudo?", "x": 1, "o": ["Siempre con fiebre", "Con una presentación diferente/atípica (confusión, caídas, síntomas inespecíficos)", "Igual que en el adulto joven", "Siempre con dolor intenso"], "k": 1, "a": "Con una presentación diferente/atípica (confusión, caídas, síntomas inespecíficos)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 27) — «53 % de 355 adultos mayores atendidos en urgencias tuvo una presentación atípica»; Tema 1, diapo 26: «la enfermedad se manifiesta con síntomas inespecíficos o en un sistema distinto al afectado». También en Andy Notas (p. 21).", "r": 1, "f": "2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}]}, {"n": 4, "titulo": "Teorías del envejecimiento", "items": [{"id": "g4-60", "q": "Con base en las teorías del envejecimiento, ¿cuál justifica el proceso de envejecimiento del caso?", "x": 1, "o": ["Teoría inmunológica del envejecimiento", "Teoría de la restricción calórica", "Teoría de la actividad de Havinhurst", "Teoría de la acumulación de mutaciones"], "k": 1, "a": "Teoría de la restricción calórica", "w": "Confirmado en Andy Notas ✔ (p. 10) — Dieta baja en calorías (1450 kcal), alta en fibra y proteínas (clave del alumno en la versión resuelta de Ene-Jun 2020).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g4-c1"}, {"id": "g4-61", "q": "Esta teoría justifica el envejecimiento del caso desde el siguiente punto de vista:", "x": 1, "o": ["Mantener la actividad al mismo nivel el mayor tiempo posible, con involucro social, laboral y económico", "El envejecimiento exitoso está programado genéticamente; el sistema inmune y endocrino son importantes", "Dieta con restricción de calorías que evita la formación de radicales libres", "Las mutaciones posteriores a la reproducción alteran la síntesis proteica"], "k": 2, "a": "Dieta con restricción de calorías que evita la formación de radicales libres", "w": "Confirmado en Andy Notas ✔ (p. 10) — Clave del alumno en la versión resuelta de ene-jun 2020.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g4-c1"}, {"id": "g4-62", "q": "Con base en la clasificación de López et al. 2013 (\"Hallmarks of aging\"), ¿qué categoría corresponde a la teoría del caso?", "x": 1, "o": ["Teorías primarias", "Teorías secundarias", "Teorías antagónicas", "Teorías integrativas"], "k": 2, "a": "Teorías antagónicas", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 21) — «Antagonistas (respuesta al daño): detección de nutrientes desregulada, disfunción mitocondrial, senescencia celular». La restricción calórica actúa sobre la detección de nutrientes. También en Andy Notas (p. 10).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g4-c1"}, {"id": "g4-63", "q": "El daño al ADN juega un papel importante en la génesis del envejecimiento; se citan dos fenómenos asociados al cambio de su estructura. Señale el correcto:", "x": 5, "o": ["Codificadores de metabolismo de lípidos", "Metilación y acetilación de proteínas histónicas", "Gestión de radicales libres", "Desestructuración del citoesqueleto"], "k": 1, "a": "Metilación y acetilación de proteínas histónicas", "w": "Confirmado en Andy Notas ✔ (p. 3)", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g4-64", "q": "Señale el origen del daño resultado de procesos intrínsecos:", "x": 5, "o": ["Exposición solar y fotoenvejecimiento por rayos UV", "Tabaquismo y sedentarismo", "Glicación y glicoxidación de ácidos nucleicos", "Daño resultado de enfermedades comunes con la edad"], "k": 2, "a": "Glicación y glicoxidación de ácidos nucleicos", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 6, diapo 9) — Proceso propio del organismo: «La glucosa juega un papel en el entrecruzamiento glicosilando las proteínas (Teoría de la Glicosilación)», que también afecta «DNA y enzimas». Las demás opciones son daño externo (sol, tabaco). También en BAIRONOTAS (p. 11).", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g4-65", "q": "Los procesos se determinan de modo aleatorio y acumulado en el transcurso del tiempo, como consecuencia de la suma de agresiones del medio ambiente, hasta ser incompatibles con la vida o la función. ¿Qué teoría biológica corresponde a este grupo?", "x": 3, "o": ["Antagonismo pleiotrópico", "Entrecruzamiento", "Soma desechable", "Acumulación de mutaciones"], "k": 1, "a": "Entrecruzamiento", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 19) — «Estocásticas: daño acumulado»: radicales libres, error-catástrofe y «entrecruzamiento: enlaces cruzados en colágeno y otras proteínas reducen su elasticidad y función». El soma desechable y el antagonismo pleiotrópico no están en este grupo. También en Andy Notas (p. 6).", "nt": "Nota: En Ago-Dic 2022 se dio por buena \"entrecruzamiento\" o \"acumulación de mutaciones\".", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g4-66", "q": "¿Qué teorías en particular pudieran contribuir más ampliamente con la razón del envejecimiento?", "x": 3, "o": ["Teoría del soma desechable, antagonismo pleiotrópico y acumulación de mutaciones", "Teorías genéticas, telomerasas y soma desechable", "Error catastrófico, acumulación de mutaciones y radicales libres", "Radicales libres y uso y desgaste"], "k": 0, "a": "Teoría del soma desechable, antagonismo pleiotrópico y acumulación de mutaciones", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 6, diapo 28) — «En particular la teoría de la acumulación de mutaciones, antagonismo pleiotrópico y la teoría del soma desechable pudieran contribuir más ampliamente con la razón del envejecimiento». También en Andy Notas (p. 9).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g4-67", "q": "Según los \"Hallmarks of ageing\" de 2013, ¿cuál de las siguientes es considerada causa de daño primario?", "x": 3, "o": ["Alteración de la comunicación intercelular", "Disfunción mitocondrial", "Alteraciones epigenéticas", "Senescencia celular"], "k": 2, "a": "Alteraciones epigenéticas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 21) — «Primarios (causan el daño): inestabilidad genómica, desgaste de telómeros, alteraciones epigenéticas, pérdida de la proteostasis, macroautofagia deficiente». También en Andy Notas (p. 9).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g4-68", "q": "De los Hallmarks del envejecimiento (2013/2023), ¿cuál se considera un factor primario?", "x": 2, "o": ["Senescencia celular", "Inflamación crónica", "Inestabilidad genómica", "Disfunción mitocondrial"], "k": 2, "a": "Inestabilidad genómica", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 1, diapo 21) — «Primarios (causan el daño): inestabilidad genómica, desgaste de telómeros, alteraciones epigenéticas, pérdida de la proteostasis, macroautofagia deficiente». También en Andy Notas (p. 9).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g4-69", "q": "Teoría del envejecimiento que trata del fin del periodo reproductivo: cumplido su objetivo de preservar la especie y dada su baja contribución futura, no es costeable energéticamente mantener el organismo.", "x": 1, "o": ["Teoría de los telómeros", "Teoría del antagonismo pleiotrópico", "Teoría del incremento en la mortalidad envejecida", "Teoría del soma desechable"], "k": 3, "a": "Teoría del soma desechable", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 6, diapo 25) — Soma desechable: energía limitada para «la capacidad reproductiva y el soma»; «a partir de la reproducción hay una declinación natural». El antagonismo pleiotrópico, en cambio, habla de genes que dan «máximo vigor» y luego dañan. También en BAIRONOTAS (p. 15).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g4-70", "q": "Entre los factores intrínsecos del envejecimiento encontramos:", "x": 2, "o": ["Radicales superóxido", "Tabaquismo", "Radiación UV", "Contaminación"], "k": 0, "a": "Radicales superóxido", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 1, diapo 19) — «Radicales libres: el daño oxidativo a lípidos, proteínas y ADN se acumula con el tiempo (Harman, 1956)». También en BAIRONOTAS (p. 12).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g4-71", "q": "Teoría que explica el envejecimiento por el declive de la inversión de energía en el mantenimiento del soma tras la reproducción:", "x": 2, "o": ["Error catastrófico", "Teoría del soma desechable", "Antagonismo pleiotrópico", "Teoría de los telómeros"], "k": 1, "a": "Teoría del soma desechable", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 6, diapo 25) — Soma desechable (Kirkwood, 1977): «El organismo tiene limitada cantidad de energía para mantener la capacidad reproductiva y el soma… A partir de la reproducción hay una declinación natural». También en Andy Notas (p. 9).", "r": 1, "f": "Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}, {"id": "g4-72", "q": "\"El envejecimiento es producto de la negligencia biológica después de la reproducción\" corresponde a:", "x": 1, "o": ["Teorías evolucionistas (soma desechable)", "Teoría del entrecruzamiento", "Teoría inmunológica", "Teoría de radicales libres"], "k": 0, "a": "Teorías evolucionistas (soma desechable)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 6, diapo 25) — «A partir de la reproducción hay una declinación natural» (soma desechable, teoría evolucionista; diapo 27: «Evolutionary theory… Disposable soma theory»). También en Andy Notas (p. 10).", "r": 1, "f": "Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}]}, {"n": 5, "titulo": "Trastornos de memoria (demencia, deterioro cognitivo y delirium)", "items": [{"id": "g5-73", "q": "¿Cuál es su diagnóstico?", "x": 5, "o": ["Depresión con pseudodemencia", "Delirium", "Deterioro cognitivo leve", "Trastorno neurocognitivo mayor, probablemente relacionado a enfermedad de Alzheimer"], "k": 3, "a": "Trastorno neurocognitivo mayor, probablemente relacionado a enfermedad de Alzheimer", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 7, diapo 10) — Criterios de TNM: «declive cognitivo significativo… en uno o más dominios» y «los déficits cognitivos interfieren con la autonomía del individuo en actividades cotidianas». Alzheimer es la causa más común: «65-85 %» (diapo 12). También en Andy Notas (p. 26).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave) · opciones reconstruidas (el original no las conservó)", "c": "g5-c1"}, {"id": "g5-74", "q": "Son características clínicas esperadas en este paciente de acuerdo al probable diagnóstico:", "x": 5, "o": ["Cambios de personalidad y desinhibición tempranos", "Dificultad para encontrar palabras, errores gramaticales y dificultad para la planeación de actividades y tareas", "Signos neurológicos focales y deterioro escalonado", "Alucinaciones visuales y parkinsonismo tempranos"], "k": 1, "a": "Dificultad para encontrar palabras, errores gramaticales y dificultad para la planeación de actividades y tareas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 7) — Lenguaje en el deterioro neurocognitivo: «Dificultad para encontrar palabras · Pausas en las oraciones · Sustituyen palabras con términos erróneos o menos complejos». También en Andy Notas (p. 26).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave) · opciones reconstruidas (el original no las conservó)", "c": "g5-c1"}, {"id": "g5-75", "q": "El manejo adecuado para este paciente sería:", "x": 5, "o": ["Antipsicótico atípico y benzodiacepina", "Inhibidores de acetilcolinesterasa, terapia de estimulación cognitiva y control de factores de riesgo", "Solo vigilancia con MMSE anual", "Antidepresivo tricíclico"], "k": 1, "a": "Inhibidores de acetilcolinesterasa, terapia de estimulación cognitiva y control de factores de riesgo", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 7, diapo 24) — Tratamiento cognitivo: «Inhibidores acetilcolinesterasa · Memantina». La estimulación cognitiva no aparece en la diapositiva. También en Andy Notas (p. 26).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave) · opciones reconstruidas (el original no las conservó)", "c": "g5-c1"}, {"id": "g5-76", "q": "Son características del delirium:", "x": 5, "o": ["Es agudo, afecta la personalidad de manera definitiva", "Es agudo, reversible, afecta la memoria y la praxis", "Es agudo, afecta la orientación y la atención", "Es agudo, fluctuante e irreversible"], "k": 2, "a": "Es agudo, afecta la orientación y la atención", "w": "Confirmado en Andy Notas con matiz (p. 24) — Andy no tiene capítulo de delirium; lo menciona como diagnóstico a excluir. Se dejó la clave.", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos)", "c": "g5-c2"}, {"id": "g5-77", "q": "¿Cuáles son las áreas cognitivas afectadas?", "x": 3, "o": ["Alteración de la atención, agnosia, apraxia y afasia", "Juicio, memoria, apraxia y lenguaje", "Memoria reciente, agnosia, apraxia, lenguaje y funciones ejecutivas", "Memoria reciente, lenguaje y orientación"], "k": 2, "a": "Memoria reciente, agnosia, apraxia, lenguaje y funciones ejecutivas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 15) — Síntomas cognitivos: «Atención, memoria, orientación · Funciones instrumentales: Lenguaje, Praxias, Gnosias · Capacidades ejecutivas». También en la GPC IMSS-456-11.", "nt": "Nota: ⚠ Dudosa: en los exámenes se recordaron claves distintas (2020: \"atención, agnosia, apraxia y afasia\"; 2022: \"memoria reciente, lenguaje y orientación\"). Se eligió la opción que coincide con los criterios de la GPC.", "d": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g5-c2"}, {"id": "g5-78", "q": "¿Cuál es el diagnóstico probable?", "x": 3, "o": ["Depresión", "Demencia vascular", "Enfermedad por cuerpos de Lewy", "Enfermedad de Alzheimer"], "k": 1, "a": "Demencia vascular", "w": "Confirmado en Andy Notas ✔ (p. 28) — Inicio súbito con deterioro escalonado y marcha de pasos cortos orientan a demencia vascular.", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g5-c2"}, {"id": "g5-79", "q": "¿Cuál de los medicamentos que toma exacerba la alteración cognitiva?", "x": 3, "o": ["Tamsulosina", "Metformina", "Metoprolol", "Paroxetina"], "k": 2, "a": "Metoprolol", "w": "No viene en tus documentos — Es la clave de 2020-2022. Tus documentos no lo resuelven; ojo: la paroxetina es anticolinérgica y también afecta la cognición.", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g5-c2"}, {"id": "g5-80", "q": "¿Cuál es el diagnóstico más probable?", "x": 3, "o": ["Demencia por cuerpos de Lewy", "Delirium", "Enfermedad de Alzheimer con síntomas psicóticos", "Deterioro cognoscitivo leve"], "k": 1, "a": "Delirium", "w": "Confirmado en BAIRONOTAS con matiz (p. 26) — Bairo cita los anticolinérgicos como causa de confusión en el adulto mayor; el cuadro agudo y fluctuante es delirium.", "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021)", "c": "g5-c3"}, {"id": "g5-81", "q": "¿Cuál es la causa etiológica probable?", "x": 3, "o": ["Disminución de la biodisponibilidad de acetilcolina", "Acúmulos de alfa-sinucleína", "Acúmulos de placas de beta-amiloide", "Aumento de la biodisponibilidad de acetilcolina"], "k": 0, "a": "Disminución de la biodisponibilidad de acetilcolina", "w": "Confirmado en BAIRONOTAS con matiz (p. 26) — Efecto anticolinérgico de la clorfeniramina.", "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021)", "c": "g5-c3"}, {"id": "g5-82", "q": "¿Cuál es el tratamiento establecido?", "x": 3, "o": ["Inhibidores de la COMT", "Inhibidores de la acetilcolinesterasa", "Anticuerpos monoclonales contra beta-amiloide", "Tratamiento de la causa"], "k": 3, "a": "Tratamiento de la causa", "w": "Confirmado en GPC IMSS-465-11 ✔ — \"Tratamiento de todas las causas subyacentes\". En Ago-Dic 2022 se discutió también \"inhibidor de acetilcolinesterasa\".", "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021)", "c": "g5-c3"}, {"id": "g5-83", "q": "¿Cuál de las características NO es un factor de riesgo significativo para caídas?", "x": 1, "o": ["Lateropulsión", "Edad", "Pravastatina", "Deterioro cognitivo"], "k": 2, "a": "Pravastatina", "w": "Confirmado en Andy Notas ✔ (p. 42) — Los fármacos de riesgo son sedantes, psicotrópicos y antihipertensivos; la estatina no.", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g5-c4"}, {"id": "g5-84", "q": "¿Qué medidas disminuyen de manera más importante el riesgo de caídas?", "x": 1, "o": ["Suplemento de calcio solo", "Ejercicio de fortalecimiento de miembros inferiores", "Reposo en cama", "Uso de restricción física"], "k": 1, "a": "Ejercicio de fortalecimiento de miembros inferiores", "w": "Confirmado en Andy Notas ✔ (p. 44)", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g5-c4"}, {"id": "g5-85", "q": "De acuerdo al resultado del MMSE (18), ¿cuál es el tratamiento?", "x": 1, "o": ["Rivastigmina (inhibidor de acetilcolinesterasa)", "Haloperidol", "Diazepam", "Ninguno"], "k": 0, "a": "Rivastigmina (inhibidor de acetilcolinesterasa)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 7, diapo 24) — Tratamiento cognitivo: «Inhibidores acetilcolinesterasa · Memantina». La diapositiva no da puntos de corte del MMSE. También en Andy Notas (p. 26).", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g5-c4"}, {"id": "g5-86", "q": "¿Cuál es la primera impresión diagnóstica?", "x": 1, "o": ["Depresión", "Demencia, probable Alzheimer", "Deterioro cognitivo leve", "Delirium"], "k": 1, "a": "Demencia, probable Alzheimer", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 7, diapo 10) — Las fallas en tareas del hogar, pagos y citas cumplen «los déficits cognitivos interfieren con la autonomía… en actividades cotidianas» (TNM); Alzheimer es el más frecuente, «65-85 %» (diapo 12). También en Andy Notas (p. 26).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g5-c5"}, {"id": "g5-87", "q": "Señale el manejo farmacológico inicial en esta paciente:", "x": 1, "o": ["Dieta y ejercicio individualizado", "Rivastigmina", "Fluoxetina", "Ginkgo biloba"], "k": 1, "a": "Rivastigmina", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 7, diapo 24) — Tratamiento cognitivo de primera elección en la diapositiva: «Inhibidores acetilcolinesterasa» (la rivastigmina lo es); después «Memantina». También en Andy Notas (p. 26).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g5-c5"}, {"id": "g5-88", "q": "¿Cuáles son las áreas cognitivas afectadas?", "x": 1, "o": ["Juicio, memoria, apraxia, lenguaje", "Alteración de la atención, amnesia reciente, apraxia, afasia", "Memoria reciente, agnosia, apraxia, lenguaje, funciones ejecutivas", "Memoria reciente, registro, lenguaje y funciones ejecutivas"], "k": 2, "a": "Memoria reciente, agnosia, apraxia, lenguaje, funciones ejecutivas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 15) — Síntomas cognitivos: «Atención, memoria, orientación · Funciones instrumentales: Lenguaje, Praxias, Gnosias · Capacidades ejecutivas». También en la GPC IMSS-456-11.", "nt": "Nota: ⚠ Dudosa: el examen no marcó clave; se eligió la opción que coincide con los criterios de la GPC.", "d": 1, "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g5-c6"}, {"id": "g5-89", "q": "¿Cuál es el diagnóstico más probable?", "x": 1, "o": ["Depresión", "Demencia vascular", "Enfermedad por inclusión de cuerpos de Lewy", "Enfermedad de Alzheimer"], "k": 3, "a": "Enfermedad de Alzheimer", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 7, diapo 12) — Prevalencia de TNM: «Enfermedad de Alzheimer 65-85 %», frente a vascular «2-10 %» y Lewy «15-30 %». También en Andy Notas (p. 26).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g5-c6"}, {"id": "g5-90", "q": "Impresión diagnóstica:", "x": 2, "o": ["Enfermedad de Alzheimer", "Depresión", "Envejecimiento normal sin quejas", "Deterioro cognitivo leve"], "k": 3, "a": "Deterioro cognitivo leve", "w": "Confirmado en BAIRONOTAS ✔ (p. 43)", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g5-c7"}, {"id": "g5-91", "q": "Velocidad de la marcha (0.9 m/s):", "x": 2, "o": ["Normal", "Lenta, criterio de fragilidad", "No valorable", "Muy lenta"], "k": 0, "a": "Normal", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 11, diapo 17) — Fried, lentitud: «tiempo para caminar 15 pies (4.57 m): ≥7 s» (o ≥6 s según la talla), es decir, menos de ≈0.65-0.76 m/s. Con 0.9 m/s no cumple el criterio, por eso la clave la da por normal. También en Andy Notas (p. 48).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g5-c7"}, {"id": "g5-92", "q": "El paciente solicita mayor evaluación de su problema. ¿Qué indica?", "x": 2, "o": ["TAC de cráneo urgente", "Punción lumbar", "Evaluación neuropsicológica", "Iniciar donepezilo"], "k": 2, "a": "Evaluación neuropsicológica", "w": "No viene en tus documentos — Se dejó la clave.", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g5-c7"}, {"id": "g5-93", "q": "¿Cuál de las siguientes características describe mejor la demencia vascular?", "x": 3, "o": ["Ausencia de factores de riesgo cardiovascular", "Signos o síntomas neurológicos focales", "Alucinaciones visuales tempranas", "Inicio insidioso sin focalización"], "k": 1, "a": "Signos o síntomas neurológicos focales", "w": "Confirmado en Andy Notas ✔ (p. 28) — La ausencia de signos focales hace improbable el diagnóstico. En 2023 y 2025 la clave fue \"todas/A y C son correctas\" (las opciones no se conservaron).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-94", "q": "Condición de pérdida de memoria leve presente en los últimos 12 meses, corroborada por el cuidador, que no incapacita la independencia en las actividades cotidianas y no cumple criterios de demencia:", "x": 2, "o": ["Deterioro cognitivo leve", "Pseudodemencia depresiva", "Trastorno neurocognitivo mayor", "Delirium"], "k": 0, "a": "Deterioro cognitivo leve", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 9) — DSM-5: «Trastorno neurocognitivo menor (TNm), o también conocido como deterioro cognitivo leve (DCL)»; el mayor «sería el equivalente a… demencia». También en BAIRONOTAS (p. 43).", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-95", "q": "¿Cuál es la demencia más común y su tratamiento en una \"señora con olvidos\" progresivos?", "x": 3, "o": ["Enfermedad de Alzheimer; donepezilo (inhibidor de colinesterasa)", "Demencia frontotemporal; memantina", "Demencia vascular; aspirina", "Demencia por cuerpos de Lewy; levodopa"], "k": 0, "a": "Enfermedad de Alzheimer; donepezilo (inhibidor de colinesterasa)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 12) — «Enfermedad de Alzheimer 65-85 %» (la más común); tratamiento: «Inhibidores acetilcolinesterasa» (donepezilo) (diapo 24). También en Andy Notas (p. 26).", "r": 1, "f": "Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017), Ene-Jun 2015, Recopilación 26 nov 2013 · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-96", "q": "¿Cuál es el tipo de delirium más común en el adulto mayor (GPC)?", "x": 2, "o": ["Delirium hiperactivo", "Delirium preclínico", "Delirium mixto", "Delirium prodrómico"], "k": 2, "a": "Delirium mixto", "w": "No viene en tus documentos — Ni en la GPC IMSS-465-11, que describe los tres subtipos (hipoactivo, hiperactivo y mixto) sin decir cuál es el más frecuente. Clave del alumno de 2020 y la recordada en 2017.", "nt": "Nota: ⚠ Dudosa (opinión, sin fuente verificada): en ancianos muchas fuentes señalan al hipoactivo como el más frecuente.", "d": 1, "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g5-97", "q": "Son características del delirium:", "x": 2, "o": ["Es una enfermedad crónica e insidiosa", "Es prevenible y reversible", "Su curso es estable sin fluctuaciones", "En general no se altera la conciencia"], "k": 1, "a": "Es prevenible y reversible", "w": "Confirmado en GPC IMSS-465-11 ✔ — La GPC lo describe como \"potencialmente prevenible y tratable\" y \"usualmente\" reversible.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g5-98", "q": "¿Qué diferencia al trastorno neurocognitivo menor del mayor?", "x": 1, "o": ["La edad de inicio", "El deterioro en las actividades de la vida diaria (pérdida de independencia)", "El resultado de la TAC", "La presencia de alteración de memoria"], "k": 1, "a": "El deterioro en las actividades de la vida diaria (pérdida de independencia)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 10) — El criterio que define al TNM es que «los déficits cognitivos interfieren con la autonomía del individuo en actividades cotidianas». También en BAIRONOTAS (p. 43).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-99", "q": "Funciones mentales que se deterioran con el envejecimiento:", "x": 1, "o": ["Vocabulario y conocimiento semántico", "Lenguaje expresivo", "Juicio y personalidad", "Velocidad de procesamiento, atención y memoria"], "k": 3, "a": "Velocidad de procesamiento, atención y memoria", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 4) — «Áreas con deterioro asociado a envejecimiento»: «Velocidad de procesamiento», «Atención múltiple o dividida», «Funciones ejecutivas» y «Memoria». La velocidad de procesamiento «disminuye después de la 3era década» (diapo 3).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-100", "q": "¿Cuáles pertenecen a los síntomas psicológicos y conductuales del trastorno neurocognitivo mayor?", "x": 1, "o": ["Afasia y apraxia", "Fiebre y leucocitosis", "Delirios, alucinaciones y depresión", "Ataxia y temblor"], "k": 2, "a": "Delirios, alucinaciones y depresión", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 7, diapo 16) — Síntomas psicológicos y conductuales: «Delirios · Alucinaciones · Depresión · Apatía · Ansiedad…». También en BAIRONOTAS (p. 42).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-101", "q": "Enfermedades que deben excluirse en el diagnóstico de TNC mayor según el DSM-5, EXCEPTO:", "x": 1, "o": ["Hipotiroidismo", "Delirium", "Depresión", "Evento vascular cerebral (stroke)"], "k": 3, "a": "Evento vascular cerebral (stroke)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 7, diapo 10) — Hay que descartar que ocurra «en el contexto de un síndrome confusional» (delirium) o que se explique «por otro trastorno mental» (depresión); los laboratorios incluyen «Hormonas tiroideas» (diapo 17). El EVC no se excluye: causa el «Trastorno neurocognitivo vascular mayor» (diapo 11).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-102", "q": "¿Cuál de los siguientes medicamentos ha mostrado mayor efectividad y seguridad para los síntomas conductuales de la demencia?", "x": 1, "o": ["Haloperidol", "Diazepam", "Citalopram", "Risperidona en dosis altas"], "k": 2, "a": "Citalopram", "w": "No viene en tus documentos — Se dejó la clave.", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-103", "q": "Defina deterioro cognitivo leve:", "x": 2, "o": ["Demencia en etapa avanzada", "Depresión con quejas de memoria", "Periodo transicional entre el envejecimiento normal y el desarrollo de demencia", "Delirium crónico"], "k": 2, "a": "Periodo transicional entre el envejecimiento normal y el desarrollo de demencia", "w": "Confirmado en BAIRONOTAS ✔ (p. 43)", "r": 1, "f": "Ene-Jun 2015, Recopilación 26 nov 2013 · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-104", "q": "Tratamiento del delirium:", "x": 2, "o": ["Inhibidores de acetilcolinesterasa", "Lorazepam como primera línea", "Tratar las causas precipitantes (y haloperidol en dosis bajas si hay agitación)", "Sujeción física"], "k": 2, "a": "Tratar las causas precipitantes (y haloperidol en dosis bajas si hay agitación)", "w": "Confirmado en GPC IMSS-465-11 con matiz — La GPC indica tratar todas las causas subyacentes; el haloperidol no aparece en el resumen consultado.", "r": 1, "f": "2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-105", "q": "Característica de la demencia:", "x": 1, "o": ["Inicio súbito y fluctuante", "Reversible al tratar la causa", "Inicio gradual (insidioso) y no reversible", "Altera primero el estado de conciencia"], "k": 2, "a": "Inicio gradual (insidioso) y no reversible", "w": "Confirmado en Andy Notas ✔ (p. 26)", "r": 1, "f": "Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g5-106", "q": "Sensibilidad del Minimental (MMSE) para demencia:", "x": 1, "o": ["Menor de 80 %", "100 %", "Mayor de 80 %", "50 %"], "k": 2, "a": "Mayor de 80 %", "w": "Confirmado en GPC IMSS-491-11 con matiz — Sensibilidad de 79-100 % (especificidad 46-100 %) para detectar deterioro cognitivo.", "nt": "Nota: ⚠ Dudosa: las diapositivas (p. 154) dan 66 %; las fuentes no coinciden. Se dejó la clave del examen porque la GPC la respalda.", "d": 1, "r": 1, "f": "2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}]}, {"n": 6, "titulo": "Trastornos afectivos y trastornos del sueño", "items": [{"id": "g6-107", "q": "¿Cuál es el diagnóstico?", "x": 5, "o": ["Probable depresión", "Duelo", "Trastorno neurocognitivo mayor", "Deterioro cognitivo leve"], "k": 0, "a": "Probable depresión", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 7) — Depresión: inicio en «semanas», curso «persistente», atención «suele preservarse», clave «anhedonia / culpa / suicidio». No es duelo (ondas ligadas a recuerdos) ni trastorno neurocognitivo (déficit objetivo progresivo). También en Andy Notas (p. 30).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g6-c1"}, {"id": "g6-108", "q": "¿Cuál es el tratamiento?", "x": 5, "o": ["Neuromoduladores a dosis baja", "Iniciar antidepresivo tricíclico", "Iniciar antidepresivo inhibidor de la recaptura de serotonina", "Iniciar inhibidor de la acetilcolinesterasa"], "k": 2, "a": "Iniciar antidepresivo inhibidor de la recaptura de serotonina", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 16) — «ISRS (p. ej., sertralina / escitalopram)»; «start low si hay fragilidad, pero titule hasta dosis terapéutica». También en Andy Notas (p. 33).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g6-c1"}, {"id": "g6-109", "q": "¿Cuál de las siguientes capacidades cognoscitivas se encuentra alterada?", "x": 1, "o": ["Praxis", "Gnosis", "Velocidad de procesamiento", "Atención"], "k": 2, "a": "Velocidad de procesamiento", "w": "CORREGIDO según las Diapositivas 2026 (Tema 5, diapo 7) — La clave era atención. Según la diapositiva, en la depresión la atención «suele preservarse» (está «marcadamente alterada» en el delirium); lo cognitivo de la depresión es «lentitud, indecisión, concentración» (Tema 5, diapo 5), que corresponde a la velocidad de procesamiento. También en Andy Notas (p. 32).", "f": "26 may 2022 (Examsoft)", "c": "g6-c1"}, {"id": "g6-110", "q": "¿Cuál es la impresión diagnóstica?", "x": 5, "o": ["Trastorno depresivo mayor con datos (síntomas) psicóticos", "Delirium", "Demencia por cuerpos de Lewy", "Esquizofrenia de inicio tardío"], "k": 0, "a": "Trastorno depresivo mayor con datos (síntomas) psicóticos", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 5) — Psicosis: «culpa, ruina, nihilismo → más probable en cuadros graves». También en Andy Notas (p. 32).", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)", "c": "g6-c2"}, {"id": "g6-111", "q": "¿Cuáles son los neurotransmisores más importantes implicados?", "x": 2, "o": ["Acetilcolina y GABA", "Histamina y noradrenalina", "Serotonina y dopamina", "Glutamato y glicina"], "k": 2, "a": "Serotonina y dopamina", "w": "Confirmado en Andy Notas con matiz (p. 32) — Andy menciona la vía serotoninérgica; la dopamina explica los síntomas psicóticos.", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g6-c2"}, {"id": "g6-112", "q": "El tratamiento adecuado es:", "x": 2, "o": ["Sertralina y olanzapina (antidepresivo + antipsicótico)", "Solo psicoterapia", "Haloperidol solo", "Diazepam"], "k": 0, "a": "Sertralina y olanzapina (antidepresivo + antipsicótico)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 14) — Con «psicosis, catatonia, riesgo suicida alto o incapacidad grave → referencia urgente; considerar tratamiento somático especializado». El ISRS de elección es sertralina (diapo 16). También en Andy Notas (p. 33).", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g6-c2"}, {"id": "g6-113", "q": "¿Cuál es una complicación frecuente de este tratamiento?", "x": 2, "o": ["Diarrea", "Caídas", "Hipoglucemia", "Hipertensión"], "k": 1, "a": "Caídas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 16) — Vigile: «hiponatremia, QT e interacciones, sangrado…, caídas / ortostatismo». También en Andy Notas (p. 42).", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g6-c2"}, {"id": "g6-114", "q": "¿Qué escala identificaría su problema (depresión geriátrica)?", "x": 3, "o": ["Katz", "Norton", "Escala de Yesavage (GDS)", "Tinetti"], "k": 2, "a": "Escala de Yesavage (GDS)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 10) — «GDS-15: útil en adultos mayores; menor carga de síntomas somáticos». Un tamiz positivo no equivale a diagnóstico. También en Andy Notas (p. 32).", "r": 1, "f": "Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g6-c2"}, {"id": "g6-115", "q": "En relación con la marcha, seleccione el inciso correcto:", "x": 2, "o": ["Marcha parkinsoniana", "Presenta una marcha normal para su edad", "Marcha atáxica", "Marcha apráxica"], "k": 1, "a": "Presenta una marcha normal para su edad", "w": "Confirmado en BAIRONOTAS con matiz (p. 62) — Con la edad disminuyen velocidad, longitud del paso y braceo y aumenta la base de sustentación.", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g6-c3"}, {"id": "g6-116", "q": "En cuanto a la actividad física a realizar, ¿cuál es la recomendación?", "x": 2, "o": ["Solo caminata ocasional", "300 minutos semanales de actividad aeróbica moderada o 150 minutos de actividad vigorosa", "30 minutos a la semana", "Reposo relativo"], "k": 1, "a": "300 minutos semanales de actividad aeróbica moderada o 150 minutos de actividad vigorosa", "w": "No viene en tus documentos — Las cifras no vienen en tus documentos; se dejó la clave.", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g6-c3"}, {"id": "g6-117", "q": "El efecto colateral más serio en este paciente de acuerdo al tratamiento con antidepresivos es:", "x": 2, "o": ["Hiponatremia", "Boca seca", "Estreñimiento", "Caídas"], "k": 3, "a": "Caídas", "w": "Claves distintas; las Diapositivas 2026 no lo resuelven (Tema 5, diapo 16) — Las diapositivas listan, sin orden de gravedad: «hiponatremia, QT e interacciones, sangrado…, caídas / ortostatismo». Ambas claves (caídas en 2024 e hiponatremia en 2025) aparecen.", "d": 1, "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g6-c3"}, {"id": "g6-118", "q": "¿Cuál sería su diagnóstico?", "x": 1, "o": ["Distimia (trastorno depresivo persistente)", "Trastorno de ansiedad", "Demencia frontotemporal", "Episodio depresivo mayor"], "k": 3, "a": "Episodio depresivo mayor", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 5) — «Tristeza puede ser poco verbalizada → predomina pérdida de interés»; perla: «la “depresión” puede presentarse como pérdida funcional sin que el paciente diga “estoy triste”». Las diapositivas no hablan de distimia; se dejó la clave.", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g6-c4"}, {"id": "g6-119", "q": "Con base en su diagnóstico, ¿cuál sería la opción terapéutica adecuada?", "x": 1, "o": ["Fluoxetina y psicoterapia", "Solo higiene del sueño", "Benzodiacepina", "Antipsicótico"], "k": 0, "a": "Fluoxetina y psicoterapia", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 14) — «TDM moderado-grave: antidepresivo + psicoterapia». Las diapositivas citan como ISRS frecuentes sertralina y escitalopram (diapo 16). También en Andy Notas (p. 33).", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g6-c4"}, {"id": "g6-120", "q": "¿Cuál es un efecto colateral de este tratamiento?", "x": 1, "o": ["Hipertensión", "Insomnio e hiporexia", "Bradicardia", "Hiperfagia"], "k": 1, "a": "Insomnio e hiporexia", "w": "Confirmado en GPC IMSS-492-11 con matiz — Los ISRS (incluida la fluoxetina) \"pueden causar insomnio como efecto secundario\".", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g6-c4"}, {"id": "g6-121", "q": "¿Cuál es el inciso correcto en cuanto a los criterios diagnósticos de trastorno depresivo mayor?", "x": 1, "o": ["Tiene 4 criterios", "Tiene 5 criterios", "Tiene 7 criterios"], "k": 2, "a": "Tiene 7 criterios", "w": "Confirmado en Andy Notas con matiz (p. 30) — Clave del alumno: se cuentan los síntomas de la paciente (tristeza, anhedonia, hiporexia, insomnio, desesperanza, ideas de muerte, inatención); el DSM pide 5 o más.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g6-c5"}, {"id": "g6-122", "q": "Uso de dos o más esquemas a dosis y tiempo suficientes sin mejoría del episodio depresivo:", "x": 1, "o": ["Respuesta", "Persistencia", "Resistencia", "Recaída"], "k": 2, "a": "Resistencia", "w": "Confirmado en Andy Notas ✔ (p. 32) — Depresión resistente: dos o más esquemas a dosis y tiempo suficientes sin mejoría.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g6-c5"}, {"id": "g6-123", "q": "En los trastornos depresivos, ¿cuál síntoma aumenta de acuerdo a la severidad del cuadro?", "x": 1, "o": ["Síntomas somáticos", "Sentimientos de inutilidad o culpa", "Quejas cognitivas", "Síntomas ansiosos"], "k": 2, "a": "Quejas cognitivas", "w": "Confirmado en Andy Notas ✔ (p. 32) — \"Las quejas cognitivas aumentan de acuerdo a la severidad\".", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g6-c5"}, {"id": "g6-124", "q": "¿Cuál es el inciso correcto respecto al resultado de la evaluación cognoscitiva?", "x": 1, "o": ["Como lo funcional no está afectado, el MMSE es irrelevante", "Profundizar y pedir BH, QS, ES, EGO, TAC, B12, folatos y VDRL", "Profundizar y pedir PET, punción lumbar, beta-amiloide y tau", "Reevaluación cognoscitiva en 5 semanas para valorar la eficacia del tratamiento"], "k": 3, "a": "Reevaluación cognoscitiva en 5 semanas para valorar la eficacia del tratamiento", "w": "Confirmado en Andy Notas con matiz (p. 32) — Clave del alumno: con MMSE limítrofe y depresión puede ser pseudodemencia; se reevalúa tras el tratamiento.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g6-c5"}, {"id": "g6-125", "q": "Diagnóstico probable:", "x": 2, "o": ["Apnea obstructiva del sueño", "Insomnio secundario", "Insomnio primario", "Narcolepsia"], "k": 1, "a": "Insomnio secundario", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 22) — Insomnio de causa «iatrogénica: fármacos, alcohol, cafeína, diuréticos, dolor». También en Andy Notas (p. 37).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g6-c6"}, {"id": "g6-126", "q": "En un viejito con insomnio, ¿qué benzodiacepina usar para prevenir caídas?", "x": 1, "o": ["Diazepam", "Clordiazepóxido", "Flurazepam", "Benzodiacepina de corta duración (a dosis bajas)"], "k": 3, "a": "Benzodiacepina de corta duración (a dosis bajas)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 28) — Las diapositivas piden «evitar de rutina benzodiazepinas» y usar «alternativas con menor… riesgo de caídas y la menor exposición posible»; de las opciones, la de corta duración es la menos riesgosa. También en Andy Notas (p. 38).", "r": 1, "f": "Diciembre 2018 (recuerdos) · opciones reconstruidas (el original no las conservó)", "c": "g6-c6"}, {"id": "g6-127", "q": "¿Cuál de las siguientes describe las características de la depresión geriátrica?", "x": 5, "o": ["La \"depresión de inicio tardío\" inicia después de los 50 años", "Su prevalencia es mayor en hombres que en mujeres (2:1)", "La ausencia de tratamiento provoca mayor riesgo de deterioro cognitivo y discapacidad funcional", "Solo a y c son correctas"], "k": 3, "a": "Solo a y c son correctas", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 2) — La depresión «no es una consecuencia normal del envejecimiento» y su impacto incluye «discapacidad y aislamiento, deterioro cognitivo funcional». Esto respalda c; el corte de 50 años de a no viene en las diapositivas. También en Andy Notas (p. 30).", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g6-128", "q": "¿Cuál de los siguientes síntomas se asocia frecuentemente a benzodiacepinas y debe considerarse al indicarlas?", "x": 5, "o": ["Hiperfagia", "Descontrol metabólico", "Arritmias", "Sedación"], "k": 3, "a": "Sedación", "w": "Confirmado en Andy Notas ✔ (p. 41)", "f": "Ene-Jun 2024 (revisión), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g6-129", "q": "En el manejo farmacológico de la depresión geriátrica, ¿cuál es el tratamiento con mayor evidencia de efectividad?", "x": 3, "o": ["Benzodiacepinas", "Antidepresivos tricíclicos", "Antidepresivos inhibidores selectivos de la recaptura de serotonina (en monoterapia)", "Antipsicóticos"], "k": 2, "a": "Antidepresivos inhibidores selectivos de la recaptura de serotonina (en monoterapia)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 16) — Opciones frecuentes: «ISRS (p. ej., sertralina / escitalopram)»; «evite paroxetina y tricíclicos con alta carga anticolinérgica». También en Andy Notas (p. 33).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g6-130", "q": "¿Cuál es un trastorno del sueño incluido en el DSM-5? (en 2023-2024 también: todos son trastornos del sueño del DSM excepto…)", "x": 3, "o": ["Jet lag", "Bruxismo diurno", "Hiperhidrosis", "Trastorno del sueño relacionado con la respiración (no lo es el jet lag)"], "k": 3, "a": "Trastorno del sueño relacionado con la respiración (no lo es el jet lag)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 22) — Trastornos de sueño-vigilia relevantes: «insomnio, respiratorios (apnea obstructiva / central, hipoventilación), piernas inquietas, parasomnias, circadianos, iatrogénicos». También en Andy Notas (p. 36).", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Ene-Jun 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g6-131", "q": "¿Cuál es uno de los elementos relevantes para el tratamiento farmacológico con inductores del sueño?", "x": 3, "o": ["Género del paciente", "Iniciar con poco y aumentar despacio la dosis (dosis efectiva más baja)", "Estado cardiovascular", "Vida media larga del medicamento"], "k": 1, "a": "Iniciar con poco y aumentar despacio la dosis (dosis efectiva más baja)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 2, diapo 14) — «START LOW: iniciar siempre con la dosis efectiva más baja posible». También en Andy Notas (p. 38).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017), Recopilación 26 nov 2013, Examen 2012"}, {"id": "g6-132", "q": "¿Cuál de los siguientes síntomas debe estar presente siempre para el diagnóstico de depresión (DSM-5)?", "x": 2, "o": ["Insomnio", "Ideación suicida", "Pérdida de peso", "Estado de ánimo depresivo (tristeza) o anhedonia (desinterés)"], "k": 3, "a": "Estado de ánimo depresivo (tristeza) o anhedonia (desinterés)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 6) — DSM-5-TR: «≥2 semanas, ≥5 síntomas; uno debe ser ánimo deprimido o anhedonia». También en Andy Notas (p. 30).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g6-133", "q": "Estudio del sueño que registra el movimiento de la mano durante el sueño por periodos prolongados, con un sensor en la muñeca, de uso doméstico:", "x": 2, "o": ["Holter", "Actigrafía", "Polisomnografía", "Electroencefalograma"], "k": 1, "a": "Actigrafía", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 26) — «Actigrafía: patrón sueño-vigilia no claro… información objetiva prolongada en casa; útil cuando el diario es poco fiable». También en Andy Notas (p. 36).", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g6-134", "q": "Mujer de 77 años con OA y DM2 (metformina y paracetamol PRN) con dificultad para iniciar el sueño de 3 semanas (tarda 3 h), sin síntomas depresivos ni olvidos. ¿Cuál es el primer paso en el tratamiento?", "x": 2, "o": ["Benzodiacepina de vida media corta", "Fitoterapia (valeriana)", "Ejercicio apropiado e higiene del sueño", "Iniciar melatonina"], "k": 2, "a": "Ejercicio apropiado e higiene del sueño", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 23) — Son 3 semanas: aún no es insomnio crónico («≥3 noches/semana · ≥3 meses + deterioro diurno»). Medidas de apoyo: horario estable, luz diurna, actividad física (diapo 29). Ojo: en el crónico, «la higiene del sueño aislada NO se recomienda como tratamiento único» (diapo 27). También en Andy Notas (p. 37).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g6-135", "q": "Se debe considerar depresión en individuos con:", "x": 1, "o": ["Trastornos del sueño, baja autoestima, pobre apetito y anergia", "Hipertensión arterial", "Fiebre", "Hiperactividad"], "k": 0, "a": "Trastornos del sueño, baja autoestima, pobre apetito y anergia", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 5) — Presentación somática: «dolor, fatiga, sueño, apetito → quejas somáticas prominentes». También en Andy Notas (p. 32).", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)"}, {"id": "g6-136", "q": "¿Cuál de las siguientes benzodiacepinas tiene la vida media más larga y no se recomienda en el adulto mayor por relacionarse con delirium y caídas?", "x": 1, "o": ["Lorazepam", "Midazolam", "Triazolam", "Diazepam"], "k": 3, "a": "Diazepam", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 2, diapo 10) — Caso de la paciente de 84 años con caídas tras «diazepam 5 mg por la noche»; Tema 5, diapo 28: «evitar de rutina: benzodiazepinas, zolpidem…». También en Andy Notas (p. 38).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g6-137", "q": "Paciente con insomnio de 5 semanas (tarda 3 h en dormir) sin higiene del sueño. ¿Cuál de los medicamentos se relaciona con insomnio?", "x": 1, "o": ["Glimepirida", "Metformina", "Levotiroxina", "Losartán"], "k": 2, "a": "Levotiroxina", "w": "Confirmado en GPC IMSS-492-11 ✔ — Las hormonas tiroideas están entre los estimulantes que pueden causar insomnio.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g6-138", "q": "Principal característica farmacológica de la benzodiacepina de elección en el adulto mayor:", "x": 1, "o": ["Liposolubilidad alta", "Potencia alta", "Vida media (corta)", "Metabolismo hepático fase 1"], "k": 2, "a": "Vida media (corta)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 5, diapo 28) — Las diapositivas piden «evitar de rutina benzodiazepinas»; si se requiere un fármaco, se usa «la menor exposición posible». También en Andy Notas (p. 38).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g6-139", "q": "¿Cuál representa un factor de riesgo asociado al uso crónico de benzodiacepinas en el adulto mayor?", "x": 1, "o": ["Hipoglucemia", "Aumento del sueño profundo", "Hipertensión", "Incremento del riesgo de caídas y fallas psicomotoras"], "k": 3, "a": "Incremento del riesgo de caídas y fallas psicomotoras", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 5, diapo 17) — Benzodiazepinas: «delirium, caídas, fracturas, deterioro psicomotor». También en Andy Notas (p. 41).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g6-140", "q": "¿Cuáles son los principales efectos de las benzodiacepinas en la arquitectura del sueño del adulto mayor?", "x": 1, "o": ["Aumento del sueño profundo (etapas 3-4)", "Ningún cambio", "Disminución del sueño MOR (REM)", "Aumento del sueño MOR"], "k": 2, "a": "Disminución del sueño MOR (REM)", "w": "Confirmado en GPC IMSS-492-11 ✔ — \"Reducen relativamente la cantidad de sueño MOR\"; además prolongan la fase 2 del sueño no MOR.", "nt": "Nota: ⚠ Dudosa (opinión): también disminuyen el sueño profundo; aun así, la GPC confirma la respuesta.", "d": 1, "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}]}, {"n": 7, "titulo": "Marcha y caídas", "items": [{"id": "g7-141", "q": "¿Cuáles son los factores de riesgo intrínsecos de inmovilidad del caso?", "x": 3, "o": ["Osteoartrosis, diabetes, depresión y polifarmacia", "Codeína, alprazolam y metoprolol", "Osteoartrosis, diabetes y depresión", "Osteoartrosis, diabetes, depresión e iluminación inadecuada"], "k": 2, "a": "Osteoartrosis, diabetes y depresión", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 8, diapo 13) — Factores intrínsecos: «Poca actividad física, alteración cognitiva, depresión, déficit sensorial, disminución de fuerza, EVC…». Los «Medicamentos» están del lado extrínseco. OA y DM no aparecen por nombre, pero son enfermedades del paciente. También en Andy Notas (p. 41).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g7-c1"}, {"id": "g7-142", "q": "¿Cuáles factores son extrínsecos?", "x": 3, "o": ["Las caídas, metoprolol, alprazolam y paracetamol", "Enalapril, metoprolol, alprazolam y codeína", "Enalapril, metoprolol, alprazolam y paracetamol", "El deterioro funcional, las caídas, alprazolam, codeína, metoprolol, enalapril y citalopram"], "k": 1, "a": "Enalapril, metoprolol, alprazolam y codeína", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 13) — «A. Factores Extrínsecos… C. Medicamentos»; en la diapo 28 los medicamentos quedan fuera del círculo intrínseco, junto al «Medio ambiente». También en Andy Notas (p. 41).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g7-c1"}, {"id": "g7-143", "q": "¿Cuál de las escalas categoriza la capacidad para la marcha (movilidad y equilibrio)?", "x": 3, "o": ["GDS", "Katz", "Lawton-Brody", "Tinetti"], "k": 3, "a": "Tinetti", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 21) — «Escala de Tinetti»: evalúa la marcha (iniciación, longitud y altura del paso, simetría, fluidez, trayectoria, tronco y postura) y el balance. También en Andy Notas (p. 42).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g7-c1"}, {"id": "g7-144", "q": "El resultado en este paciente (Tinetti 9) indica:", "x": 3, "o": ["Incapacidad para la marcha", "Alto riesgo de caída", "Bajo riesgo de caída", "No riesgo de caída"], "k": 1, "a": "Alto riesgo de caída", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 12, diapo 14) — Escala de Tinetti: «<19 Alto riesgo de caídas · 19-24 Riesgo de caídas». Con 9 puntos: alto riesgo. También en Escalas en Geriatría (p. 3).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g7-c1"}, {"id": "g7-145", "q": "La paciente realiza ejercicios de balance, fuerza, flexibilidad y condición general. Este programa:", "x": 3, "o": ["Reduce el riesgo y el número de caídas", "Aumenta el riesgo de fracturas", "Solo mejora el ánimo", "No modifica el riesgo"], "k": 0, "a": "Reduce el riesgo y el número de caídas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 26) — «Ejercicio que mejora el balance, fuerza, flexibilidad y condición física: redujo el riesgo de caídas en 12 % y el número de caídas 19 %». También en Andy Notas (p. 44).", "r": 1, "f": "Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g7-c2"}, {"id": "g7-146", "q": "Según la literatura de caídas en ancianos, ¿qué factor se relaciona más con las caídas?", "x": 2, "o": ["Edad", "Sexo femenino", "Visión", "Trastorno de la marcha y balance, o debilidad"], "k": 3, "a": "Trastorno de la marcha y balance, o debilidad", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 16) — «Lower extremity weakness» RR 4.4 y «Gait deficit» / «Balance deficit» RR 2.9; la edad >80 años tiene menos peso. También en Andy Notas (p. 42).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g7-c2"}, {"id": "g7-147", "q": "De los medicamentos que recibe, ¿cuál es el más frecuentemente asociado a caídas?", "x": 2, "o": ["Hidroclorotiazida", "Aspirina", "Losartán", "Paracetamol"], "k": 0, "a": "Hidroclorotiazida", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 8, diapo 24) — «Antihipertensivos» están entre los medicamentos de caídas; el diurético favorece la hipotensión postural («Postural hypotension», diapo 15). La diapositiva no ordena los fármacos por frecuencia. También en Andy Notas (p. 42).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g7-c2"}, {"id": "g7-148", "q": "Cambio de la marcha asociado a la edad:", "x": 2, "o": ["Disminuye la base de sustentación", "La longitud del paso se reduce", "Aumenta la velocidad", "Aumenta el braceo"], "k": 1, "a": "La longitud del paso se reduce", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 9) — Efectos de la edad sobre la marcha: «Disminución de la longitud del paso», «disminución de la velocidad», «pérdida del balanceo de los brazos» y «aumento de la anchura del paso». También en Andy Notas (p. 39).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g7-c2"}, {"id": "g7-149", "q": "La intervención geriátrica debe ser multidimensional e interdisciplinaria. Como médicos, su obligación será:", "x": 2, "o": ["Indicar sujeción", "Prescribir reposo", "Reducir factores de riesgo farmacológicos y no farmacológicos", "Solo referir a rehabilitación"], "k": 2, "a": "Reducir factores de riesgo farmacológicos y no farmacológicos", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 26) — Prevención: «Valoración multidimensional · Reducción de factores de riesgo: disminuyó el riesgo de caída 18 % y el número de caídas 43 %». También en Andy Notas (p. 44).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g7-c2"}, {"id": "g7-150", "q": "Factores extrínsecos que deben corregirse de inmediato:", "x": 2, "o": ["Retirar obstáculos y mejorar la iluminación", "Restricción física", "Uso de silla de ruedas", "Cambiar de casa"], "k": 0, "a": "Retirar obstáculos y mejorar la iluminación", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 14) — Medio ambiente: iluminación en «escaleras, puertas, pasillo al baño» y casa «libre de objetos, adornos, cables». También en Andy Notas (p. 41).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)", "c": "g7-c2"}, {"id": "g7-151", "q": "Mecanismo farmacológico más probablemente involucrado en las caídas:", "x": 1, "o": ["Arritmia", "Hipoglucemia", "Alteración del equilibrio por medicamentos", "Hipotiroidismo"], "k": 2, "a": "Alteración del equilibrio por medicamentos", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 8, diapo 24) — Medicamentos asociados a caídas: «Benzodiacepinas, antihistamínicos, analgésicos narcóticos, antidepresivos, anticonvulsivantes, antipsicóticos…, antihipertensivos». También en Andy Notas (p. 42).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g7-c3"}, {"id": "g7-152", "q": "Batería de estudios correcta para este paciente:", "x": 1, "o": ["BH, química sanguínea, perfil tiroideo, EGO, urocultivo y nivel de vitamina D", "Electromiografía", "Solo TAC de cráneo", "Ninguno"], "k": 0, "a": "BH, química sanguínea, perfil tiroideo, EGO, urocultivo y nivel de vitamina D", "w": "No viene en tus documentos — Se dejó la clave.", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g7-c3"}, {"id": "g7-153", "q": "Forma parte del sistema del equilibrio en su fase de integración postural:", "x": 1, "o": ["Retina", "Ganglios basales", "Nervio periférico", "Músculo cuádriceps"], "k": 1, "a": "Ganglios basales", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 4) — Balance: «Integración: Cerebelo, Ganglios basales, Corteza». También en Andy Notas (p. 39).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g7-c3"}, {"id": "g7-154", "q": "La explicación más probable de este cuadro es:", "x": 1, "o": ["Hipoglucemia", "Neuropatía diabética", "Polifarmacia", "Multifactorial"], "k": 3, "a": "Multifactorial", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 30) — «La causa más frecuente es multifactorial»; la paciente reúne factores intrínsecos y medicamentos (diazepam). También en Andy Notas (p. 41).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g7-c4"}, {"id": "g7-155", "q": "De los datos de la exploración, ¿cuál es el factor más importante en su motivo de consulta?", "x": 1, "o": ["Disminución de fuerza muscular 3/5 proximal de miembros inferiores", "Marcha con base amplia de sustentación", "Variabilidad en la longitud del paso", "Paso bajo y corto"], "k": 0, "a": "Disminución de fuerza muscular 3/5 proximal de miembros inferiores", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 16) — El factor de mayor riesgo es «Lower extremity weakness» (debilidad de miembros inferiores), RR 4.4. También en Andy Notas (p. 42).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g7-c4"}, {"id": "g7-156", "q": "¿A qué familia de medicamentos se le ha relacionado, con su uso crónico, con movimientos anormales (extrapiramidalismo) e inicio de terapia antiparkinsoniana?", "x": 5, "o": ["Antipsicóticos", "Inhibidores de la acetilcolinesterasa", "Antidepresivos tricíclicos", "Antiarrítmicos"], "k": 0, "a": "Antipsicóticos", "w": "Confirmado en BAIRONOTAS ✔ (p. 69) — Notas de clase: medicamentos que inducen parkinsonismo.", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g7-157", "q": "Aunque el origen de las caídas suele ser multifactorial, de manera individual, ¿cuál se considera la causa más frecuente?", "x": 5, "o": ["Medicamentos", "Enfermedad de Alzheimer", "Medio ambiente", "Parkinsonismo"], "k": 2, "a": "Medio ambiente", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 14) — Medio ambiente: «Individualmente es la causa más frecuente de caídas». En conjunto, la causa es «multifactorial» (diapo 30). También en Andy Notas (p. 42).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), Diciembre 2018 (recuerdos), Ene-Jun 2015"}, {"id": "g7-158", "q": "Se define como la serie de movimientos alternantes y rítmicos de las extremidades y del tronco que determinan un desplazamiento hacia adelante del centro de gravedad:", "x": 3, "o": ["Balance vestibular", "Equilibrio", "Caída por retropulsión", "Marcha"], "k": 3, "a": "Marcha", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 5) — «Serie de movimientos alternantes, rítmicos, de las extremidades y del tronco que determinan un desplazamiento hacia delante del centro de gravedad». También en Andy Notas (p. 39).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g7-159", "q": "Para evitar caídas, el piso debe ser no reflejante, no resbaloso y sin tapetes. Señale otra característica favorable:", "x": 3, "o": ["Con contraste de color si hay un cambio de nivel", "De material acrílico", "Con líneas entre mosaicos prominentes", "Con indicación visible de rutas donde pisar"], "k": 0, "a": "Con contraste de color si hay un cambio de nivel", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 14) — Piso: «No reflejante, no resbaloso, evitar tapetes y alfombras, contraste de color en cambio de nivel». También en las diapositivas de clase (p. 261).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g7-160", "q": "¿Qué medicamento se asocia más a caídas y delirium?", "x": 3, "o": ["Celecoxib", "Metotrexate", "Metformina", "Diazepam"], "k": 3, "a": "Diazepam", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 24) — El primer grupo de la lista de medicamentos de caídas son las «Benzodiacepinas» (diazepam); el celecoxib, el metotrexate y la metformina no aparecen. También en Andy Notas (p. 42).", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, {"id": "g7-161", "q": "De los factores de riesgo intrínsecos, ¿cuál se relaciona más con caídas?", "x": 3, "o": ["Artritis", "Uso de auxiliares de la marcha", "Disminución de fuerza en extremidades inferiores", "Déficit visuales"], "k": 2, "a": "Disminución de fuerza en extremidades inferiores", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 16) — Mayor riesgo en 16 estudios: «Lower extremity weakness» (debilidad de miembros inferiores) RR 4.4, por encima de caídas previas (3.0), alteración de la marcha (2.9), auxiliares (2.6) y déficit visual. También en Andy Notas (p. 42).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), Diciembre 2018 (recuerdos), Agosto 2016 (recuerdos)"}, {"id": "g7-162", "q": "De los siguientes fármacos, ¿cuál se relaciona más con caídas en adultos mayores?", "x": 2, "o": ["Lorazepam (en la otra versión: clonazepam)", "Levotiroxina", "Finasterida", "Metformina"], "k": 0, "a": "Lorazepam (en la otra versión: clonazepam)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 24) — «Benzodiacepinas» encabezan los medicamentos asociados a caídas; levotiroxina, finasterida y metformina no están en la lista. También en Andy Notas (p. 42).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g7-163", "q": "Factores extrínsecos de inmovilidad o riesgo de caídas:", "x": 3, "o": ["Demencia", "Depresión", "Diabetes", "Medicamentos (fármacos, iatrogenia y factores sociales)"], "k": 3, "a": "Medicamentos (fármacos, iatrogenia y factores sociales)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 8, diapo 13) — «A. Factores Extrínsecos… C. Medicamentos» y «Factores Ambientales: obstáculos, escaleras». También en Andy Notas (p. 41).", "r": 1, "f": "Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g7-164", "q": "En la evaluación del Timed Up and Go, ¿a partir de qué tiempo se correlaciona un riesgo menor (leve) de caídas?", "x": 1, "o": ["<10 segundos", "Entre 10 y 20 segundos", ">20 segundos", "No existe un valor determinado"], "k": 1, "a": "Entre 10 y 20 segundos", "w": "Confirmado en Andy Notas con matiz (p. 42) — Clave del alumno (marcada como dudosa): <10 s normal, entre 10 y 20 s riesgo leve, >20 s riesgo de caída.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g7-165", "q": "Paciente con Tinetti de 17. ¿Qué medida es apropiada?", "x": 1, "o": ["Ninguna medida", "Reposo en cama", "Facilitar el desplazamiento en casa (adaptar el ambiente)", "Sujeción física"], "k": 2, "a": "Facilitar el desplazamiento en casa (adaptar el ambiente)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 8, diapo 14) — Adaptar el ambiente: piso «no resbaloso, evitar tapetes», escaleras con «pasamanos ambos lados», baño con «barras de apoyo». Con Tinetti de 17: «<19 Alto riesgo de caídas» (Tema 12, diapo 14). También en Andy Notas (p. 41).", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)"}, {"id": "g7-166", "q": "Time Up and Go mayor de 20 segundos indica:", "x": 1, "o": ["Marcha normal", "Fragilidad severa", "Riesgo de caídas (necesita apoyo para la marcha)", "Buena movilidad"], "k": 2, "a": "Riesgo de caídas (necesita apoyo para la marcha)", "w": "Confirmado en Andy Notas ✔ (p. 42)", "r": 1, "f": "2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}, {"id": "g7-167", "q": "Prevención secundaria en el riesgo de caídas:", "x": 1, "o": ["Reposo", "Cirugía de cadera", "Adaptar el entorno", "Vacunación"], "k": 2, "a": "Adaptar el entorno", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 8, diapo 14) — El medio ambiente «individualmente es la causa más frecuente de caídas» y la diapositiva lista cómo adaptarlo; no lo clasifica como prevención primaria o secundaria.", "r": 1, "f": "Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g7-168", "q": "Paciente con debilidad de miembros inferiores y alteración de la marcha. ¿Qué recomienda según la alteración?", "x": 1, "o": ["Reposo", "Solo analgésicos", "Silla de ruedas", "Ejercicios de resistencia (fortalecimiento)"], "k": 3, "a": "Ejercicios de resistencia (fortalecimiento)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 8, diapo 26) — «Ejercicio que mejora el balance, fuerza, flexibilidad y condición física» redujo el riesgo de caídas 12 %; la debilidad de miembros inferiores es el factor de mayor riesgo (RR 4.4, diapo 16). También en Andy Notas (p. 44).", "r": 1, "f": "Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)"}, {"id": "g7-169", "q": "Fractura más frecuente por caída (sin contar las vertebrales):", "x": 1, "o": ["Fractura de Colles (radio distal)", "Fractura de cadera", "Fractura de tobillo", "Fractura de húmero"], "k": 0, "a": "Fractura de Colles (radio distal)", "w": "Confirmado en Andy Notas con matiz (p. 41) — En la comunidad, 5 % de las caídas causan fractura de muñeca y 2 % de cadera.", "r": 1, "f": "2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}, {"id": "g7-170", "q": "Factores intrínsecos de inmovilidad o riesgo de caídas:", "x": 1, "o": ["Medicamentos", "Tapetes", "DM, osteoartritis y caídas previas", "Iluminación"], "k": 2, "a": "DM, osteoartritis y caídas previas", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 8, diapo 16) — «History of falls» (caídas previas) RR 3.0 y «Arthritis» RR 2.4 son factores del paciente (intrínsecos, diapo 13); la DM no aparece por nombre. También en Andy Notas (p. 41).", "r": 1, "f": "Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}]}, {"n": 8, "titulo": "Síndrome de fragilidad", "items": [{"id": "g8-171", "q": "Se han descrito algunos probables marcadores biológicos de este problema; identifíquelos:", "x": 5, "o": ["Interleucina 6, proteína C reactiva y factor de necrosis tumoral α", "T3 reversa, TSH y yodo proteico", "Péptido C, polímero D y VSG", "Serotonina y noradrenalina"], "k": 0, "a": "Interleucina 6, proteína C reactiva y factor de necrosis tumoral α", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 11, diapo 11) — «Nivel celular: inflamación · senescencia · disfunción mitocondrial». La diapositiva habla de inflamación, pero no nombra IL-6, PCR ni TNF-α. También en Andy Notas (p. 47).", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017)", "c": "g8-c1"}, {"id": "g8-172", "q": "Detrás de este diagnóstico hay fenómenos asociados a reservas fisiológicas disminuidas, incluyendo disfunción inmunológica, cambios neuromusculares y finalmente:", "x": 5, "o": ["Cambios en la ley de Frank-Starling del gasto cardiaco", "Desregulación neuroendocrina", "Disminución del aclaramiento hepático", "Disminución del aclaramiento renal"], "k": 1, "a": "Desregulación neuroendocrina", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 11) — De la célula a la clínica: «Sistemas: cerebro · eje endocrino (HPA) · sistema inmune · músculo esquelético» → «pérdida acumulada de reserva homeostática». También en Andy Notas (p. 46).", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), Diciembre 2018 (recuerdos)", "c": "g8-c1"}, {"id": "g8-173", "q": "¿Cuál es su primera impresión diagnóstica?", "x": 5, "o": ["Sarcopenia y fragilidad del adulto mayor", "Presarcopenia y malnutrición", "Sarcopenia e hiporexia senil", "Presarcopenia y depresión mayor"], "k": 0, "a": "Sarcopenia y fragilidad del adulto mayor", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 11, diapo 17) — Fatiga, debilidad, pérdida de peso y marcha lenta: «≥3 criterios: Frágil»; la sarcopenia (pérdida muscular, pantorrilla 28 cm) es parte del «ciclo de la fragilidad» (diapo 10). También en Andy Notas (p. 47).", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g8-c1"}, {"id": "g8-174", "q": "Al establecer las causas precipitantes de los fenómenos identificados, señale lo correcto:", "x": 5, "o": ["Uso de estatina para hipercolesterolemia", "Inactividad física", "Trastorno depresivo mayor confirmado por clinimetría", "Dolor crónico persistente"], "k": 1, "a": "Inactividad física", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 11, diapo 12) — Factores de estilo de vida: «Sedentarismo e inactividad física» y «Desuso que acelera el fenotipo de envejecimiento». La depresión también es factor, pero aquí no está confirmada (GDS 5). También en Andy Notas (p. 48).", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g8-c1"}, {"id": "g8-175", "q": "Su plan incluye apoyo nutricio interdisciplinario, modificación del entorno, uso juicioso de analgésicos e intervención multidimensional. Señale lo correcto:", "x": 5, "o": ["Rehabilitación física gradual con énfasis en movilización fuera de cama y marcha", "Reemplazo hormonal con anabólicos esteroides", "Antidepresivo de acción dual (duloxetina o mirtazapina)", "Psicoterapia conductual con énfasis en autoestima"], "k": 0, "a": "Rehabilitación física gradual con énfasis en movilización fuera de cama y marcha", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 21) — «Ejercicio: la intervención de primera línea» (ICFSR 2019: multicomponente con resistencia, 1.ª línea, fuerte). Las hormonas «no recomendadas» y la testosterona tiene «poco efecto» (diapo 26). También en Andy Notas (p. 48).", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g8-c1"}, {"id": "g8-176", "q": "De acuerdo con los datos, ¿cuál sería el diagnóstico presuntivo?", "x": 3, "o": ["Depresión mayor", "Sarcopenia aislada", "Desnutrición por cáncer", "Fragilidad (síndrome de fragilidad)"], "k": 3, "a": "Fragilidad (síndrome de fragilidad)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 17) — Cumple pérdida de peso, agotamiento, lentitud y debilidad: «≥3 criterios: Frágil» (1-2 prefrágil, 0 robusto). También en Andy Notas (p. 48).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g8-c2"}, {"id": "g8-177", "q": "De acuerdo a los criterios del estadio del síndrome geriátrico, señale lo correcto:", "x": 2, "o": ["Cumple criterios de estadio 6 de fragilidad en la escala clínica de Rockwood", "No es valorable", "Estadio 9 de Rockwood", "Estadio 3 de Rockwood"], "k": 0, "a": "Cumple criterios de estadio 6 de fragilidad en la escala clínica de Rockwood", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 11, diapo 16) — Clinical Frailty Scale 2.0: «5: dependencia en AIVD», «6: ayuda en actividades fuera de casa y para el baño», «7-8: dependencia total para el cuidado personal». Con andador, Lawton 4 y Katz 5 encaja en el nivel 6. También en BAIRONOTAS (p. 77).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g8-c2"}, {"id": "g8-178", "q": "Estado fisiológico de vulnerabilidad aumentada a estresores agudos que resulta de reservas fisiológicas disminuidas y favorece complicaciones y desenlaces clínicos adversos:", "x": 5, "o": ["Envejecimiento patológico", "Sarcopenia", "Fragilidad", "Síndrome de caídas"], "k": 2, "a": "Fragilidad", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 3) — Kim y Rockwood: «Estado clínicamente identificable de reserva fisiológica disminuida y vulnerabilidad aumentada a un amplio espectro de desenlaces adversos»; Clegg: «resolución deficiente de la homeostasis tras un evento estresante». También en Andy Notas (p. 46).", "f": "Noviembre 2025, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Ene-Jun 2020 (incl. versión COVID «-1»)"}, {"id": "g8-179", "q": "De los siguientes, señale cuál corresponde a los criterios diagnósticos de fragilidad:", "x": 5, "o": ["Pérdida de peso intencionada >4.5 kg o >10 % del peso en el último año", "Sentimiento de agotamiento mental", "Fuerza de prensión de 30 kg por dinamometría", "Marcha tambaleante", "Nivel bajo de actividad física"], "k": 4, "a": "Nivel bajo de actividad física", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 17) — Criterios de Fried: pérdida de peso «no intencional >10 lb (≈4.5 kg) en el último año», agotamiento, «baja actividad física», lentitud y debilidad (prensión «en el quintil inferior»). La pérdida intencionada y una prensión de 30 kg no son criterio. También en Andy Notas (p. 48).", "nt": "Nota: En 2020 se recordó \"agotamiento físico\". En 2017 se preguntó cuál NO es criterio y se dieron todas por buenas.", "f": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g8-180", "q": "El fenotipo de fragilidad incluye:", "x": 1, "o": ["Demencia, incontinencia y caídas", "Obesidad, HTA y DM", "Bajo gasto energético, marcha lenta y fuerza de prensión disminuida", "Fiebre, leucocitosis y anemia"], "k": 2, "a": "Bajo gasto energético, marcha lenta y fuerza de prensión disminuida", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 17) — Fenotipo de Fried: «Pérdida de peso · Agotamiento · Baja actividad física (gasto <383 kcal/sem H, <270 M) · Lentitud · Debilidad»; «≥3 criterios: frágil». También en Andy Notas (p. 48).", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)"}, {"id": "g8-181", "q": "Las reservas disminuidas del individuo con síndrome de fragilidad pueden resumirse en:", "x": 2, "o": ["Hipertensión y diabetes", "Deterioro cognitivo aislado", "Cambios neuromusculares, desregulación neuroendocrina y disfunción inmunológica", "Solo pérdida de peso"], "k": 2, "a": "Cambios neuromusculares, desregulación neuroendocrina y disfunción inmunológica", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 11) — «Sistemas: cerebro · eje endocrino (HPA) · sistema inmune · músculo esquelético»: neuroendocrino, inmunológico y neuromuscular. También en Andy Notas (p. 46).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}]}, {"n": 9, "titulo": "Incontinencia urinaria y fecal", "items": [{"id": "g9-182", "q": "De acuerdo al caso clínico, ¿qué tipo de incontinencia tiene el paciente?", "x": 5, "o": ["Incontinencia por rebosamiento", "Incontinencia urinaria mixta (de urgencia y funcional)", "Incontinencia transitoria", "Incontinencia de esfuerzo"], "k": 1, "a": "Incontinencia urinaria mixta (de urgencia y funcional)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 16) — Funcional: «incapacidad… para reconocer la necesidad de orinar o de comunicar la sensación»; característica en «Enfermedad vascular cerebral». De urgencia: «fuerte deseo miccional», con «desórdenes del SNC» y «nicturia» (diapos 12-13). También en Andy Notas (p. 52).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave) · opciones reconstruidas (el original no las conservó)", "c": "g9-c1"}, {"id": "g9-183", "q": "Los factores que más se asocian a la incontinencia en este paciente son:", "x": 5, "o": ["Tabaquismo", "Solo la diabetes", "Sexo masculino y escolaridad", "Edad, poliuria, nicturia, dificultad para la marcha y polifarmacia"], "k": 3, "a": "Edad, poliuria, nicturia, dificultad para la marcha y polifarmacia", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 11) — Causas: «Fármacos», «Volumen urinario excesivo (CHF, DM)», «Movilidad restringida»; la incontinencia de urgencia «suele asociarse: polaquiuria, nicturia» (diapo 13). También en Andy Notas (p. 50).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave) · opciones reconstruidas (el original no las conservó)", "c": "g9-c1"}, {"id": "g9-184", "q": "Son criterios de referencia al especialista en incontinencia urinaria:", "x": 3, "o": ["Incontinencia urinaria refractaria al tratamiento", "IVU no complicada", "Incontinencia transitoria resuelta", "Nicturia aislada"], "k": 0, "a": "Incontinencia urinaria refractaria al tratamiento", "w": "No viene en tus documentos — Se dejó la clave.", "r": 1, "f": "Noviembre 2025, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave) · opciones reconstruidas (el original no las conservó)", "c": "g9-c1"}, {"id": "g9-185", "q": "Son criterios de referencia al especialista, EXCEPTO:", "x": 2, "o": ["Ardor al orinar, tenesmo, leucocituria, esterasas y nitritos en el EGO (infección: se trata en primer nivel)", "Hematuria sin infección", "Retención urinaria", "Incontinencia refractaria al tratamiento"], "k": 0, "a": "Ardor al orinar, tenesmo, leucocituria, esterasas y nitritos en el EGO (infección: se trata en primer nivel)", "w": "No viene en tus documentos — Los criterios de referencia no vienen en tus documentos; se dejó la clave.", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g9-c1"}, {"id": "g9-186", "q": "¿Qué factor de riesgo tiene esta paciente para incontinencia urinaria?", "x": 3, "o": ["Edad", "Uso de medicamentos bloqueadores alfa (prazosina)", "Estreñimiento", "Paroxetina"], "k": 1, "a": "Uso de medicamentos bloqueadores alfa (prazosina)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 10) — «Bloqueadores alfa-adrenérgicos: relajación uretral». También en las diapositivas de clase (p. 328).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g9-c2"}, {"id": "g9-187", "q": "¿Qué tipo de incontinencia tiene esta paciente?", "x": 3, "o": ["Incontinencia urinaria de urgencia", "De esfuerzo", "Por rebosamiento", "Funcional"], "k": 0, "a": "Incontinencia urinaria de urgencia", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 12) — Urgencia: «Pérdida involuntaria de orina asociada a un fuerte deseo miccional». También en Andy Notas (p. 51).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g9-c2"}, {"id": "g9-188", "q": "¿En qué tipo de incontinencia está indicada la cirugía?", "x": 1, "o": ["(Se dieron todas las opciones como correctas en Mayo 2023)", "Urgencia", "Funcional", "Transitoria"], "k": 0, "a": "(Se dieron todas las opciones como correctas en Mayo 2023)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 27) — «La cirugía se reserva para el tratamiento de la incontinencia de esfuerzo, incluyendo la suspensión del cuello vesical y técnicas de cabestrillo». Si el examen trae «de esfuerzo», esa es la respuesta. También en Andy Notas (p. 53).", "r": 1, "f": "Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g9-c2"}, {"id": "g9-189", "q": "¿Qué tipo de incontinencia urinaria padece este paciente?", "x": 3, "o": ["Incontinencia urinaria aguda (transitoria)", "Incontinencia urinaria de esfuerzo", "Incontinencia urinaria persistente", "Incontinencia urinaria por inestabilidad del trígono"], "k": 0, "a": "Incontinencia urinaria aguda (transitoria)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 8) — Transitoria: «Inicio súbito. Presentación aguda sobre una enfermedad de fondo»; causa: «Fármacos: anticolinérgicos: retención urinaria, incontinencia por rebosamiento» (diapo 9). Ojo: en 2022-2024 la versión equivalente se respondió \"por rebosamiento\". También en Andy Notas (p. 51).", "f": "Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos)", "c": "g9-c3"}, {"id": "g9-190", "q": "¿Cuál es la fisiopatología involucrada?", "x": 3, "o": ["Los medicamentos causan disminución en la capacidad de contracción vesical", "Alteración anatómica que impide el funcionamiento normal", "Disminución de la capacidad vesical de almacenamiento por envejecimiento", "Medicamentos que aumentan la contracción del detrusor"], "k": 0, "a": "Los medicamentos causan disminución en la capacidad de contracción vesical", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 9) — «Anticolinérgicos: retención urinaria, incontinencia por rebosamiento»: disminuyen la contracción vesical. También en Andy Notas (p. 50).", "f": "Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos)", "c": "g9-c3"}, {"id": "g9-191", "q": "¿Cuál es el tratamiento apropiado?", "x": 3, "o": ["Ejercicios de Kegel y fenilpropanolamina", "Alfabloqueador y suspensión de la imipramina", "Suspensión de hidroclorotiazida e imipramina", "Suspensión de imipramina y agregar un alfaagonista"], "k": 1, "a": "Alfabloqueador y suspensión de la imipramina", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 10) — Las diapositivas no dan el tratamiento del rebosamiento, pero apoyan la clave: los antidepresivos tienen «acción anticolinérgica» (retención) y los bloqueadores alfa producen «relajación uretral».", "f": "Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos)", "c": "g9-c3"}, {"id": "g9-192", "q": "Los estudios paraclínicos adecuados son:", "x": 2, "o": ["Flujometría, BH, QS, ES, calcio, ECG, tele de tórax, EGO y urocultivo", "BH, QS, ES, ECG, tele de tórax, calcio, EGO y urocultivo", "Flujometría, US con orina residual y tonometría de esfínter", "BH, QS, ES, calcio, urocultivo, EGO y US con medición de orina residual"], "k": 3, "a": "BH, QS, ES, calcio, urocultivo, EGO y US con medición de orina residual", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 20) — Estudios: «Examen de orina», «Cultivo de orina» y evaluación urológica; la diapositiva no menciona la medición de orina residual por US. También en Andy Notas (p. 52).", "f": "Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g9-c3"}, {"id": "g9-193", "q": "¿Qué tipo de incontinencia tiene?", "x": 2, "o": ["De esfuerzo", "Funcional", "Incontinencia por rebosamiento", "De urgencia"], "k": 2, "a": "Incontinencia por rebosamiento", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 15) — Rebosamiento: «Pérdida involuntaria de orina en una vejiga hiperdistendida… pérdida constante… de pequeñas cantidades»; «flujo débil o interrumpido». También en Andy Notas (p. 52).", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g9-c4"}, {"id": "g9-194", "q": "Los estudios paraclínicos adecuados serían:", "x": 2, "o": ["BH, QS, ES, EGO, urocultivo y US con medición de orina residual", "Cistoscopia de entrada", "TAC abdominal", "Solo EGO"], "k": 0, "a": "BH, QS, ES, EGO, urocultivo y US con medición de orina residual", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 20) — Estudios: «Examen de orina», «Cultivo de orina» y evaluación urológica; la diapositiva no menciona la medición de orina residual por US. También en Andy Notas (p. 52).", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g9-c4"}, {"id": "g9-195", "q": "¿Cuál de los siguientes factores probablemente causa la incontinencia?", "x": 2, "o": ["Hiperactividad del detrusor", "Probable HPB, y los medicamentos disminuyen la capacidad de contracción vesical", "Fístula vesical", "Debilidad del piso pélvico"], "k": 1, "a": "Probable HPB, y los medicamentos disminuyen la capacidad de contracción vesical", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 9) — «Anticolinérgicos: retención urinaria, incontinencia por rebosamiento»; los antidepresivos (imipramina) tienen «acción anticolinérgica» (diapo 10). También en Andy Notas (p. 50).", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g9-c4"}, {"id": "g9-196", "q": "Tratamiento apropiado según el tipo de incontinencia:", "x": 2, "o": ["Sonda permanente", "Ejercicios de Kegel solamente", "Oxibutinina", "Alfabloqueador y suspender la imipramina"], "k": 3, "a": "Alfabloqueador y suspender la imipramina", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 10, diapo 10) — Las diapositivas no dan el tratamiento del rebosamiento, pero apoyan la clave: los antidepresivos tienen «acción anticolinérgica» (retención) y los bloqueadores alfa producen «relajación uretral».", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g9-c4"}, {"id": "g9-197", "q": "¿Qué tipo de incontinencia tiene?", "x": 1, "o": ["Incontinencia de esfuerzo", "Incontinencia funcional", "Incontinencia por rebosamiento", "Incontinencia mixta"], "k": 2, "a": "Incontinencia por rebosamiento", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 9) — Causa transitoria: «Impactación fecal»; rebosamiento: «pérdida constante… en una vejiga hiperdistendida» (diapo 15). También en Andy Notas (p. 52).", "f": "26 may 2022 (Examsoft)", "c": "g9-c5"}, {"id": "g9-198", "q": "Una maniobra diagnóstica importante consistiría en:", "x": 1, "o": ["Examen rectal digital", "Evaluación funcional geriátrica", "Determinación del volumen vesical postmiccional", "Pruebas neurofisiológicas"], "k": 0, "a": "Examen rectal digital", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 19) — Exploración física: «Abdominal · Rectal · Pélvico» (el tacto rectal busca la impactación fecal, diapo 9). También en Andy Notas (p. 52).", "f": "26 may 2022 (Examsoft)", "c": "g9-c5"}, {"id": "g9-199", "q": "Paciente de 85 años que toma paracetamol con codeína, con bradipsiquia; refiere orina en cantidad moderada a abundante. ¿Qué tipo de incontinencia tiene?", "x": 2, "o": ["Por rebosamiento crónica", "Funcional permanente", "Transitoria", "De esfuerzo"], "k": 2, "a": "Transitoria", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 10) — «Analgésicos narcóticos: retención urinaria, impactación fecal, sedación, delirium»; son causa de incontinencia transitoria (diapo 11: «Fármacos»). También en Andy Notas (p. 50).", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g9-200", "q": "¿Cuál es el tratamiento de esa incontinencia?", "x": 2, "o": ["Cirugía", "Tratar la enfermedad (causa) de base", "Sonda permanente", "Oxibutinina"], "k": 1, "a": "Tratar la enfermedad (causa) de base", "w": "Confirmado en Andy Notas ✔ (p. 51)", "r": 1, "f": "Recopilación 26 nov 2013, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g9-201", "q": "Si se dan muchos anticolinérgicos, ¿qué complicaciones pueden aparecer?", "x": 2, "o": ["Diarrea y taquipnea", "Hiperglucemia", "Hipertensión", "Retención urinaria (incontinencia por rebosamiento), delirium y estreñimiento"], "k": 3, "a": "Retención urinaria (incontinencia por rebosamiento), delirium y estreñimiento", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 9) — «Anticolinérgicos: retención urinaria, incontinencia por rebosamiento, impactación». También en Andy Notas (p. 50).", "r": 1, "f": "2017 (recuerdos, incl. junio 2017), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g9-202", "q": "Pérdida constante y continua de pequeñas cantidades de orina con vejiga distendida:", "x": 1, "o": ["Incontinencia por rebosamiento", "Incontinencia funcional", "Incontinencia de urgencia", "Incontinencia de esfuerzo"], "k": 0, "a": "Incontinencia por rebosamiento", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 15) — «Pérdida involuntaria de orina en una vejiga hiperdistendida. Pérdida constante, tanto periódica como continua de pequeñas cantidades de orina». También en Andy Notas (p. 52).", "r": 1, "f": "2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}, {"id": "g9-203", "q": "Tratamiento de primera línea de la incontinencia de esfuerzo:", "x": 1, "o": ["Ejercicios de Kegel (piso pélvico)", "Terapia cognitivo-conductual", "Sonda vesical", "Antimuscarínicos"], "k": 0, "a": "Ejercicios de Kegel (piso pélvico)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 10, diapo 24) — «Ejercicios de Kegel: recomendados para incontinencia de urgencia, de estrés y mixta»; tres series de 8-12 contracciones, 3-4 veces por semana, 15-20 semanas. También en Andy Notas (p. 53).", "r": 1, "f": "2017 (recuerdos, incl. junio 2017) · opciones reconstruidas (el original no las conservó)"}]}, {"n": 10, "titulo": "Nutrición", "items": [{"id": "g10-204", "q": "En base al caso clínico, ¿cuál es el diagnóstico probable?", "x": 1, "o": ["Malnutrición, diabetes mellitus, estreñimiento, fragilidad y probable sarcopenia", "Desnutrición, diabetes, síndrome de fragilidad, estreñimiento y caídas", "Malnutrición, diabetes mellitus, hiporexia y sarcopenia", "(Opción no recordada)"], "k": 0, "a": "Malnutrición, diabetes mellitus, estreñimiento, fragilidad y probable sarcopenia", "w": "Confirmado en Andy Notas con matiz (p. 70) — El examen no marcó respuesta. Prensión baja, pantorrilla <31 cm (Andy p. 67) y marcha lenta (<0.8 m/s) orientan a sarcopenia.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g10-c1"}, {"id": "g10-205", "q": "¿Cuál es el tratamiento más adecuado?", "x": 1, "o": ["Retirar la dieta keto, iniciar dieta de 1600 kcal a base de suplementos para llegar a 60 kg, terapia física diaria y estimulación del apetito", "Retirar la dieta keto, iniciar 1700 kcal con énfasis en carbohidratos, terapia física aeróbica con periodos de reposo, dieta rica en fibra y 2 litros de agua al día", "Retirar la dieta keto, 1800 kcal con énfasis en proteínas, terapia física escalonada hasta ejercicio anaeróbico con periodos de reposo y control glucémico estricto", "Retirar la dieta keto, 1800 kcal con énfasis en proteínas para llegar a 60 kg, terapia física escalonada para mejorar fuerza, equilibrio y balance, dieta rica en fibra e ingesta de 8 vasos de agua (250 ml)"], "k": 3, "a": "Retirar la dieta keto, 1800 kcal con énfasis en proteínas para llegar a 60 kg, terapia física escalonada para mejorar fuerza, equilibrio y balance, dieta rica en fibra e ingesta de 8 vasos de agua (250 ml)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 9, diapo 12) — «Las dietas hipocalóricas o los periodos de ayuno… pueden favorecer… la producción de cuerpos cetónicos, el catabolismo proteico» (por eso se retira la keto); energía «30 kcal/kg/día» (diapo 4) y agua mínimo «8 vasos de agua al día» (diapo 30). También en Andy Notas (p. 66).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g10-c1"}, {"id": "g10-206", "q": "¿Cuál es el requerimiento diario de proteínas si su objetivo terapéutico de IMC es 24?", "x": 1, "o": ["82 gramos", "72 gramos", "62 gramos", "52 gramos"], "k": 0, "a": "82 gramos", "w": "Claves distintas; las Diapositivas 2026 no lo resuelven (Tema 11, diapo 23) — La diapositiva da «1.2-1.5 g/kg/día ante enfermedad aguda o crónica» (1.0-1.2 en sanos), pero no dice qué peso usar. Con 54 kg × 1.5 ≈ 81 g (clave); con el peso meta (≈62 kg) serían 75-93 g.", "nt": "Nota: ⚠ Dudosa: la pregunta pide calcular con el peso meta (IMC 24 ≈ 62 kg) y ninguna opción cuadra bien con 1.5 g/kg.", "d": 1, "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g10-c1"}, {"id": "g10-207", "q": "¿Cuál es la recomendación diaria de proteínas en un adulto mayor con sarcopenia (o enfermedad crónica), según las guías de nutrición clínica e hidratación de la ESPEN 2018?", "x": 5, "o": ["0.8 g/kg/día", "1.5 g/kg/día", "3 g/kg/día", "1 g/kg/día"], "k": 1, "a": "1.5 g/kg/día", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 23) — Proteína «1.2-1.5 g/kg/día ante enfermedad aguda o crónica» (1.0-1.2 en sanos); Tema 9, diapo 10: «las necesidades proteicas aumentan en relación con la gravedad y la duración de la enfermedad». También en BAIRONOTAS (p. 101).", "f": "Noviembre 2025, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g10-208", "q": "Nutriente antioxidante cuya carencia se asocia a disminución de la inmunidad, mala cicatrización de heridas, menor capacidad gustativa, inapetencia y anorexia:", "x": 5, "o": ["Magnesio", "Zinc", "Selenio", "Hierro"], "k": 1, "a": "Zinc", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 23) — Zinc: «Nutriente antioxidante… Su carencia se asocia a una disminución de la inmunidad, de la cicatrización de las heridas, de la capacidad gustativa, a la inapetencia o anorexia y a la degeneración macular». También en Andy Notas (p. 65).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-209", "q": "¿Cuál es la recomendación diaria de energía en un adulto mayor sano, según las guías de la ESPEN 2018?", "x": 3, "o": ["30 kcal/kg/día", "35 kcal/kg/día", "30 kJ/kg/día", "20 kcal/kg/día"], "k": 0, "a": "30 kcal/kg/día", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 4) — Recomendación de energía (ESPEN 2018): «30 kcal/kg/día». También en Andy Notas (p. 63).", "f": "Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g10-210", "q": "¿Cuál es la recomendación diaria de fibra en un adulto mayor sano, según las guías de la ESPEN 2018?", "x": 3, "o": ["25 mg/día", "10 g/kg/día", "25 g/kg/día", "25 g/día"], "k": 3, "a": "25 g/día", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 18) — Fibra según la guía ESPEN de nutrición e hidratación en geriatría: 25 g/día. También en Andy Notas (p. 65).", "f": "Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g10-211", "q": "Las necesidades proteicas en personas de edad avanzada están influidas por:", "x": 3, "o": ["Aumento del gasto energético", "Ingesta calórica por debajo de lo recomendado, disminución del compartimento muscular, infecciones y enfermedades crónicas", "Aumento de la masa muscular", "Solo la edad cronológica"], "k": 1, "a": "Ingesta calórica por debajo de lo recomendado, disminución del compartimento muscular, infecciones y enfermedades crónicas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 6) — Necesidades proteicas: «Ingesta calórica por debajo de los niveles recomendados», «dificultad [en la] utilización eficaz de las proteínas», «Disminución del compartimento muscular» y «Enfermedades crónicas». También en Andy Notas (p. 64).", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-212", "q": "Los siguientes factores influyen en el aumento de la necesidad proteica de los pacientes de edad avanzada, EXCEPTO:", "x": 2, "o": ["Disminución del compartimento muscular", "Infecciones y enfermedades crónicas", "Aumento del compartimento muscular que condiciona una menor disponibilidad de aminoácidos para la síntesis proteica", "Ingesta calórica por debajo de los niveles recomendados"], "k": 2, "a": "Aumento del compartimento muscular que condiciona una menor disponibilidad de aminoácidos para la síntesis proteica", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 6) — Lo que aumenta la necesidad proteica es la «Disminución del compartimento muscular que condiciona menor disponibilidad de aminoácidos para la síntesis proteica» (no su aumento). También en Andy Notas (p. 64).", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-213", "q": "Las necesidades de qué tipo de nutriente están influidas por la disminución del compartimento muscular:", "x": 3, "o": ["Grasas", "Agua", "Carbohidratos", "Proteínas"], "k": 3, "a": "Proteínas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 6) — «Disminución del compartimento muscular que condiciona menor disponibilidad de aminoácidos para la síntesis proteica» → proteínas. También en Andy Notas (p. 64).", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017), Ene-Jun 2015"}, {"id": "g10-214", "q": "Consumo óptimo de proteínas en el adulto mayor:", "x": 3, "o": ["4 g/kg/día", "2 a 3 g/kg/día", "0.3 a 0.5 g/kg/día", "0.8 a 1 g/kg/día"], "k": 3, "a": "0.8 a 1 g/kg/día", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 9, diapo 8) — Recomendación de proteína: «1 g/kg/día» (ESPEN 2018). El Tema 11 (diapo 23) da «1.0-1.2 g/kg/día de proteína en adultos mayores sanos (PROT-AGE)». La opción 0.8-1 es la que más se acerca; ojo si el examen pone 1 g/kg/día. También en Andy Notas (p. 64).", "r": 1, "f": "Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-215", "q": "¿Qué factores influyen en el aumento de la necesidad proteica de los pacientes de edad avanzada?", "x": 1, "o": ["La disminución de la ingesta de grasas", "Las infecciones y enfermedades crónicas", "El aumento de la masa muscular", "El sexo femenino"], "k": 1, "a": "Las infecciones y enfermedades crónicas", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 10) — «Las necesidades proteicas aumentan en relación con la gravedad y la duración de la enfermedad»; diapo 6: «Enfermedades crónicas». También en Andy Notas (p. 64).", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-216", "q": "¿Cuál es la recomendación de consumo de proteínas diaria en el adulto mayor sano, para la población mexicana?", "x": 1, "o": ["1 g/kg/día", "2 g/kg/día", "0.5 g/kg/día", "1.5 g/kg/día"], "k": 0, "a": "1 g/kg/día", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 8) — Recomendación de proteína (ESPEN 2018): «1 g/kg/día», ajustada a estado nutricional, actividad física, morbilidades y tolerancia. También en Andy Notas (p. 64).", "r": 1, "f": "Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-217", "q": "Recomendación de fibra en México:", "x": 1, "o": ["25 g/kg/día", "40-50 g/día", "18-25 g/día y 20-25 g/día (se dieron dos respuestas correctas)", "5-10 g/día"], "k": 2, "a": "18-25 g/día y 20-25 g/día (se dieron dos respuestas correctas)", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 9, diapo 19) — Por intolerancias y menor ingesta, «algunos países como Francia e Inglaterra recomiendan entre 18-20 g/día»; la recomendación ESPEN es 25 g/día (diapo 18). También en Andy Notas (p. 65).", "r": 1, "f": "Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-218", "q": "Su deficiencia provoca aumento en los niveles de homocisteína sérica:", "x": 2, "o": ["Calcio y vitamina D", "Vitamina A y E", "Ácido fólico, vitamina B6 y B12", "Zinc y selenio"], "k": 2, "a": "Ácido fólico, vitamina B6 y B12", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 28) — «Ácido fólico, vitamina B6 y B12: el déficit… se relaciona con niveles anormales de homocisteína en sangre», que inducen enfermedad coronaria, cerebrovascular y demencia. También en Andy Notas (p. 66).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-219", "q": "Síntoma de déficit proteico en el adulto mayor:", "x": 2, "o": ["Poliuria", "Prurito (además de edema, eczema, debilidad muscular, retraso en la cicatrización, fatiga y alteración inmunológica)", "Taquicardia", "Hipertensión"], "k": 1, "a": "Prurito (además de edema, eczema, debilidad muscular, retraso en la cicatrización, fatiga y alteración inmunológica)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 9) — Déficit proteico-calórico: «Edema, eczema crónico, debilidad muscular, retraso en la cicatrización, prurito cutáneo, fatiga…». También en Andy Notas (p. 64).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-220", "q": "Un aporte menor de 1500 kcal/día supone:", "x": 1, "o": ["Riesgo de obesidad", "Un aporte adecuado para el adulto mayor", "Exceso de proteínas", "Riesgo de baja ingesta de vitaminas y minerales"], "k": 3, "a": "Riesgo de baja ingesta de vitaminas y minerales", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 5) — «Aportes menores de 1500 calorías/día suponen riesgo de baja ingesta de vitaminas y minerales». También en Andy Notas (p. 64).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-221", "q": "Requerimiento nutricional que es similar al de la población general:", "x": 1, "o": ["Agua", "Grasas (no más del 30 % del total energético; hasta 35 % si es aceite de oliva)", "Proteínas", "Energía"], "k": 1, "a": "Grasas (no más del 30 % del total energético; hasta 35 % si es aceite de oliva)", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 9, diapo 15) — Grasas: «similares al resto de la población»; «no sobrepasen el 30 % del total energético… hasta un 35 % cuando el aceite de oliva es la grasa de adición mayoritaria». También en Andy Notas (p. 65).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)"}, {"id": "g10-222", "q": "A una paciente con pérdida de masa muscular le indican cloroquina. ¿Qué suplemento le da?", "x": 1, "o": ["Calcio", "Vitamina A", "Zinc", "Hierro y proteínas"], "k": 3, "a": "Hierro y proteínas", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 9, diapo 22) — Hierro: factores que predisponen a su carencia, «Enfermedades inflamatorias»; y la pérdida de músculo aumenta la necesidad de proteínas (diapo 6). La diapositiva no menciona la cloroquina.", "r": 1, "f": "Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}]}, {"n": 11, "titulo": "Úlceras por presión y problemas del pie", "items": [{"id": "g11-223", "q": "Define 2 de los mecanismos fisiopatológicos principales de las úlceras por presión:", "x": 5, "o": ["Incontinencia urinaria y fecal", "Humedad y piel seca", "Poca movilización (inmovilidad) y cizallamiento", "Infecciones recurrentes"], "k": 2, "a": "Poca movilización (inmovilidad) y cizallamiento", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 12, diapo 25) — En el inmovilizado: cambiar de posición «cada 1-2 horas, evitar presión sobre prominencias óseas» y «no arrastrar al paciente para evitar las fuerzas de cizallamiento y fricción». También en Andy Notas (p. 56).", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g11-c1"}, {"id": "g11-224", "q": "¿Qué grado es esta úlcera por presión?", "x": 5, "o": ["Grado I", "Grado II", "Grado III", "Grado IV"], "k": 3, "a": "Grado IV", "w": "Confirmado en Andy Notas ✔ (p. 56) — Grado IV: úlcera profunda con músculo, tendón y/o hueso visibles.", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g11-c1"}, {"id": "g11-225", "q": "¿Qué parámetros evalúa la escala de Norton?", "x": 5, "o": ["Estado físico, estado mental, incontinencia fecal y urinaria y alimentación", "Estado físico, estado mental, movilidad, actividad e incontinencia", "Estado mental, grado de actividad, tamaño y profundidad de la úlcera y sitio de presión", "Días de movilidad, incontinencia, sitios de presión y enfermedades concomitantes"], "k": 1, "a": "Estado físico, estado mental, movilidad, actividad e incontinencia", "w": "Confirmado en Andy Notas ✔ (p. 57) — 5 a 20 puntos; <12 es de riesgo.", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g11-c1"}, {"id": "g11-226", "q": "¿Cuáles son las medidas de prevención que deberían indicarse a los pacientes con alto riesgo de úlcera por presión?", "x": 5, "o": ["Cambios posturales, colchón neumático, cuidado de la piel y apoyo nutricional", "Cambios posturales, colchón neumático, óxido de zinc y lavados con solución fisiológica", "Cuidados de la piel, colchón neumático, uso de donas y sulfadiazina", "Colchón neumático, hidratación, movilidad y masajes sobre el área de presión"], "k": 0, "a": "Cambios posturales, colchón neumático, cuidado de la piel y apoyo nutricional", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 12, diapo 25) — Prevención en inmovilidad total: «cambiar de posición cada 1-2 horas, evitar presión sobre prominencias óseas», «proteger zona sacra»; la diapositiva no menciona el colchón. También en Andy Notas (p. 58).", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)", "c": "g11-c1"}, {"id": "g11-227", "q": "¿Qué grado de úlcera por presión tiene?", "x": 1, "o": ["Grado I", "Grado II", "Grado III", "Grado IV"], "k": 2, "a": "Grado III", "w": "Confirmado en Andy Notas con matiz (p. 56) — Úlcera profunda sin músculo, tendón ni hueso visibles; Andy no menciona la escara como criterio.", "f": "26 may 2022 (Examsoft)", "c": "g11-c2"}, {"id": "g11-228", "q": "Además de las medidas de movilidad y alivio de la presión, ¿cuál es el tratamiento principal?", "x": 1, "o": ["Desbridación y apósitos húmedos cada 2 horas", "Desbridación, limpieza cada 2 horas y levofloxacino 500 mg c/24 h VO", "Desbridación, limpieza cada 2 horas y mupirocina (Bactroban) tópica c/8 h", "Apósitos húmedos frecuentes"], "k": 1, "a": "Desbridación, limpieza cada 2 horas y levofloxacino 500 mg c/24 h VO", "w": "Confirmado en Andy Notas ✔ (p. 58) — Con fiebre e hiperemia (inflamación sistémica) se indica antibiótico sistémico.", "f": "26 may 2022 (Examsoft)", "c": "g11-c2"}, {"id": "g11-229", "q": "Una semana después está afebril; la úlcera está húmeda, con ligera secreción amarillenta en el borde y escara de 0.5 cm. ¿Cuál sería el tratamiento principal?", "x": 1, "o": ["Desbridación y apósitos húmedos cada 2 horas", "Desbridación, limpieza cada 2 horas y levofloxacino 500 mg c/24 h VO", "Desbridación, limpieza cada 2 horas y mupirocina (Bactroban) tópica c/8 h", "Apósitos húmedos frecuentes"], "k": 2, "a": "Desbridación, limpieza cada 2 horas y mupirocina (Bactroban) tópica c/8 h", "w": "Confirmado en Andy Notas ✔ (p. 58) — Antibiótico tópico en úlceras grado III-IV con datos locales de infección.", "f": "26 may 2022 (Examsoft)", "c": "g11-c2"}, {"id": "g11-230", "q": "Tres semanas después la úlcera es más pequeña, con bordes y fondo limpios, secos, sin secreción y con áreas de granulación. ¿Tratamiento principal?", "x": 1, "o": ["Desbridación y apósitos húmedos cada 2 horas", "Desbridación, limpieza cada 2 horas y levofloxacino", "Desbridación, limpieza cada 2 horas y mupirocina tópica", "Apósitos húmedos frecuentes"], "k": 3, "a": "Apósitos húmedos frecuentes", "w": "Confirmado en Andy Notas ✔ (p. 57) — El apósito ideal mantiene el lecho húmedo.", "f": "26 may 2022 (Examsoft)", "c": "g11-c2"}, {"id": "g11-231", "q": "Con lo detallado, ¿cuántos apartados de la escala de Norton se pueden valorar en este paciente?", "x": 1, "o": ["6", "3", "5", "4"], "k": 2, "a": "5", "w": "Confirmado en Andy Notas con matiz (p. 57) — El examen no marcó respuesta. Norton tiene 5 apartados y todos se describen en el caso.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g11-c3"}, {"id": "g11-232", "q": "¿Cuál es el grado de la úlcera?", "x": 1, "o": ["Grado 1", "Grado 2", "Grado 3", "Grado 4"], "k": 2, "a": "Grado 3", "w": "Confirmado en Andy Notas con matiz (p. 56) — El examen no marcó respuesta. Exposición de tejido graso = grado III.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g11-c3"}, {"id": "g11-233", "q": "¿Cuáles son las fuerzas involucradas en la fisiopatología de las úlceras por presión?", "x": 1, "o": ["Inmovilidad, incontinencia y desnutrición", "Presión, cizallamiento y humedad", "Inmovilidad, deterioro cognitivo y piel seca", "Tensión, cizallamiento y fricción"], "k": 1, "a": "Presión, cizallamiento y humedad", "w": "Confirmado en Andy Notas con matiz (p. 56) — El examen no marcó respuesta. Andy describe presión, cizallamiento, fricción y humedad.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g11-c3"}, {"id": "g11-234", "q": "¿Qué recomendación farmacológica y no farmacológica le haría?", "x": 1, "o": ["Curación con solución salina, sulfadiazina de plata y ciprofloxacino VO", "Suplementos altos en proteínas, movilización continua, cuidados de la piel y curaciones con solución salina", "Suplementos altos en proteínas, desbridación autolítica, movilización continua y manejo del dolor", "Curación con agua oxigenada, tallado estricto, movilización, cremas lubricantes y control del dolor"], "k": 2, "a": "Suplementos altos en proteínas, desbridación autolítica, movilización continua y manejo del dolor", "w": "Confirmado en Andy Notas con matiz (p. 58) — Clave del alumno. Suplementos proteicos, desbridación (autolítica: no dolorosa), movilización y analgesia; el agua oxigenada está contraindicada.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g11-c3"}, {"id": "g11-235", "q": "Escala que evalúa el riesgo de úlceras por presión:", "x": 3, "o": ["Escala de Katz", "Escala de Tinetti", "Escala de Yesavage", "Escala de Norton"], "k": 3, "a": "Escala de Norton", "w": "Confirmado en Andy Notas ✔ (p. 57)", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-236", "q": "¿Cuál es la complicación más frecuente en pacientes con úlceras por presión?", "x": 2, "o": ["Fístula uretero-perineal", "Úlcera de Marjolin", "Septicemia", "Formación de hueso heterotópico"], "k": 2, "a": "Septicemia", "w": "Confirmado en Andy Notas ✔ (p. 58) — Se asocia al 40 % de las muertes por úlceras.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g11-237", "q": "En problemas podiátricos, es la causa más frecuente de talalgia:", "x": 2, "o": ["Pie plano valgo del adulto", "Hallux valgus", "Fascitis plantar", "Dedos en garra"], "k": 2, "a": "Fascitis plantar", "w": "Confirmado en Andy Notas ✔ (p. 62)", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}, {"id": "g11-238", "q": "Características de la úlcera por presión estadio II:", "x": 3, "o": ["Eritema que no palidece con piel intacta", "Exposición de tejido graso", "Exposición de músculo o hueso", "Superficial; parece abrasión, ampolla o cráter, con daño de epidermis, dermis o ambas"], "k": 3, "a": "Superficial; parece abrasión, ampolla o cráter, con daño de epidermis, dermis o ambas", "w": "Confirmado en Andy Notas ✔ (p. 56)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-239", "q": "Según los estadios de UPP, existe una pérdida total de la piel que involucra daño y necrosis del tejido subcutáneo:", "x": 1, "o": ["Estadio 1", "Estadio 4", "Estadio 3", "Estadio 2"], "k": 2, "a": "Estadio 3", "w": "CORREGIDO según Andy Notas (p. 56) — La clave del examen fue \"estadio 4\", pero en tus notas el daño del tejido subcutáneo (grasa visible) es grado III; el IV requiere músculo, tendón o hueso (también Escalas p. 6).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-240", "q": "¿Cómo se clasifican los pacientes según la escala de Norton de riesgo de UPP?", "x": 1, "o": ["Grados I a IV", "Riesgo leve, moderado y severo", "Por colores", "Solo con y sin riesgo"], "k": 1, "a": "Riesgo leve, moderado y severo", "w": "Confirmado en Escalas en Geriatría con matiz (p. 6) — ≤14 puntos riesgo evidente y ≤12 riesgo muy alto.", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-241", "q": "Tipos de fuerzas involucradas en la formación de la UPP:", "x": 1, "o": ["Tensión y torsión", "Solo presión", "Humedad y calor", "Presión, fricción y cizallamiento"], "k": 3, "a": "Presión, fricción y cizallamiento", "w": "★ Confirmado en Diapositivas 2026 con matiz (Tema 12, diapo 25) — «Evitar presión sobre prominencias óseas» y «no arrastrar al paciente para evitar las fuerzas de cizallamiento y fricción». También en Andy Notas (p. 56).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-242", "q": "Método de desbridación más selectivo y no doloroso para las UPP:", "x": 1, "o": ["Mecánico", "Quirúrgico", "Químico", "Autolítico"], "k": 3, "a": "Autolítico", "w": "Confirmado en Andy Notas ✔ (p. 58) — Hidratación del lecho, fibrinólisis y enzimas endógenas; es más lento.", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-243", "q": "Dolor en la tuberosidad calcánea:", "x": 1, "o": ["Inflamación de la fascia plantar (fascitis plantar)", "Metatarsalgia", "Hallux valgus", "Dedos en garra"], "k": 0, "a": "Inflamación de la fascia plantar (fascitis plantar)", "w": "Confirmado en Andy Notas ✔ (p. 62)", "r": 1, "f": "Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-244", "q": "Desviación externa (lateral) del primer ortejo:", "x": 1, "o": ["Hallux rigidus", "Hallux valgus", "Pie plano", "Dedos en garra"], "k": 1, "a": "Hallux valgus", "w": "Confirmado en Andy Notas ✔ (p. 61)", "r": 1, "f": "Mayo 2023 · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-245", "q": "El estadio IV de las úlceras por presión se caracteriza por:", "x": 2, "o": ["Eritema no blanqueable", "Ampolla", "Exposición de tejido graso", "Ser una úlcera profunda que llega a músculo, tendón o hueso (debajo de la fascia)"], "k": 3, "a": "Ser una úlcera profunda que llega a músculo, tendón o hueso (debajo de la fascia)", "w": "Confirmado en Andy Notas ✔ (p. 56)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Diciembre 2018 (recuerdos) · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-246", "q": "Señale un sitio común de úlceras por presión en el adulto mayor:", "x": 1, "o": ["Abdomen", "Occipucio únicamente", "Sacro, isquion, trocánter mayor y calcáneo", "Palma de la mano"], "k": 2, "a": "Sacro, isquion, trocánter mayor y calcáneo", "w": "Confirmado en Andy Notas ✔ (p. 56)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)"}, {"id": "g11-247", "q": "Puntaje de la escala de Norton que indica riesgo:", "x": 1, "o": ["Igual a 20", "Mayor de 15", "Mayor de 18", "Menor de 12"], "k": 3, "a": "Menor de 12", "w": "Confirmado en Andy Notas ✔ (p. 57)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)"}]}, {"n": 12, "titulo": "Sarcopenia e hiporexia", "items": [{"id": "g12-248", "q": "¿Qué intervención no farmacológica es la más adecuada para este paciente?", "x": 3, "o": ["Sonda nasogástrica inmediata", "Ayuno y reposo", "Dieta líquida exclusiva", "Dieta fraccionada alta en fibra, suplemento proteico, rehabilitación física y mejorar el sabor de los alimentos"], "k": 3, "a": "Dieta fraccionada alta en fibra, suplemento proteico, rehabilitación física y mejorar el sabor de los alimentos", "w": "Confirmado en Andy Notas ✔ (p. 69)", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g12-c1"}, {"id": "g12-249", "q": "Los siguientes factores contribuyen en mayor medida al diagnóstico de desnutrición en este paciente:", "x": 3, "o": ["Hemoglobina normal", "IMC de 30", "Circunferencia de pantorrilla <31 cm, albúmina sérica disminuida y pérdida de peso >3 kg en los últimos 3 meses", "Colesterol elevado"], "k": 2, "a": "Circunferencia de pantorrilla <31 cm, albúmina sérica disminuida y pérdida de peso >3 kg en los últimos 3 meses", "w": "Confirmado en Andy Notas con matiz (p. 67) — Tus notas usan albúmina <3.5 g/dl (la clave decía <2.5).", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g12-c1"}, {"id": "g12-250", "q": "Señale el factor de riesgo asociado a la anorexia y pérdida de peso:", "x": 2, "o": ["Edad", "Sexo masculino", "Hipertensión", "Disminución de la actividad física (en Mayo 2023: \"disminución de la actividad física, estreñimiento y deterioro cognitivo\")"], "k": 3, "a": "Disminución de la actividad física (en Mayo 2023: \"disminución de la actividad física, estreñimiento y deterioro cognitivo\")", "w": "Confirmado en Andy Notas con matiz (p. 69) — Tus notas incluyen la inmovilidad (estreñimiento) y la demencia como factores de la anorexia.", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g12-c1"}, {"id": "g12-251", "q": "Señale el factor que se considera asociado a la anorexia geriátrica:", "x": 1, "o": ["Aumento de la colecistocinina con la edad", "Disminución del péptido YY", "Disminución de la leptina", "Aumento de la grelina"], "k": 0, "a": "Aumento de la colecistocinina con la edad", "w": "Confirmado en Andy Notas ✔ (p. 69)", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)", "c": "g12-c1"}, {"id": "g12-252", "q": "¿Cuál es el diagnóstico por criterios clínicos del Consenso Europeo (EWGSOP)?", "x": 1, "o": ["Sarcopenia / sarcopenia severa (se dieron dos incisos como correctos)", "Caquexia", "Presarcopenia", "Fragilidad sin sarcopenia"], "k": 0, "a": "Sarcopenia / sarcopenia severa (se dieron dos incisos como correctos)", "w": "Confirmado en Andy Notas con matiz (p. 70) — Fuerza baja = probable sarcopenia; + masa baja = sarcopenia; + desempeño bajo = sarcopenia severa.", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g12-c2"}, {"id": "g12-253", "q": "Factores de riesgo que pueden estar asociados a la evolución del diagnóstico:", "x": 1, "o": ["Exceso de ejercicio", "Edad, anorexia del envejecimiento, depresión y sedentarismo / hiporexia senil, síntomas depresivos, movilidad limitada y pérdida de fuerza (2 incisos correctos)", "Solo la genética", "Hipertiroidismo"], "k": 1, "a": "Edad, anorexia del envejecimiento, depresión y sedentarismo / hiporexia senil, síntomas depresivos, movilidad limitada y pérdida de fuerza (2 incisos correctos)", "w": "Confirmado en Andy Notas con matiz (p. 70)", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g12-c2"}, {"id": "g12-254", "q": "¿Qué cambios biológicos del envejecimiento pueden influir en el deterioro del apetito?", "x": 1, "o": ["Aumento de grelina", "Aumento del olfato", "Disminución de CCK", "Elevación de leptina; elevación de CCK y disminución de grelina; disminución del olfato y gusto (se dieron 3 correctas)"], "k": 3, "a": "Elevación de leptina; elevación de CCK y disminución de grelina; disminución del olfato y gusto (se dieron 3 correctas)", "w": "Confirmado en Andy Notas ✔ (p. 68)", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g12-c2"}, {"id": "g12-255", "q": "Respecto a la hiporexia del adulto mayor, ¿qué aseveración es correcta?", "x": 1, "o": ["Aumenta la grelina", "El vaciamiento gástrico está acelerado en todas sus fases", "La saciedad dura menos", "El vaciamiento gástrico de líquidos es acelerado y el mixto (líquido-sólido) retrasado"], "k": 3, "a": "El vaciamiento gástrico de líquidos es acelerado y el mixto (líquido-sólido) retrasado", "w": "Confirmado en Andy Notas ✔ (p. 68)", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g12-c2"}, {"id": "g12-256", "q": "Según la escala del índice de fragilidad, ¿en qué categoría está este paciente?", "x": 1, "o": ["Categoría 5", "Categoría 7", "Categoría 9", "Categoría 2"], "k": 0, "a": "Categoría 5", "w": "No viene en tus documentos — Se dejó la clave: el caso se recordó incompleto y no se puede ubicar en la escala. La escala de Rockwood (FACT 2014) viene en las diapositivas (p. 316).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g12-c2"}, {"id": "g12-257", "q": "¿Cuál sería la recomendación terapéutica?", "x": 1, "o": ["Testosterona", "Reposo y dieta hipocalórica", "Ejercicio de resistencia, asegurar proteína de 1-1.5 g/kg y suplementar vitamina D si hay déficit", "Hormona de crecimiento"], "k": 2, "a": "Ejercicio de resistencia, asegurar proteína de 1-1.5 g/kg y suplementar vitamina D si hay déficit", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 11, diapo 23) — Proteína «1.0-1.2 g/kg/día» en sanos y «1.2-1.5 g/kg/día ante enfermedad aguda o crónica»; «Vitamina D: solo si deficiencia»; el ejercicio es «la intervención de primera línea» (diapo 21). «La nutrición potencia al ejercicio». También en Andy Notas (p. 72).", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)", "c": "g12-c2"}, {"id": "g12-258", "q": "¿Cuáles son las hormonas involucradas en la etiología de la anorexia senil?", "x": 5, "o": ["Colecistocinina, péptido YY y leptina", "Insulina, cortisol y grelina", "TSH y T4", "Cortisol y TSH"], "k": 0, "a": "Colecistocinina, péptido YY y leptina", "w": "Confirmado en Andy Notas ✔ (p. 69)", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g12-259", "q": "¿Qué drogas orexigénicas conoce para el tratamiento de la anorexia senil?", "x": 5, "o": ["Ciproheptadina y megestrol", "Amantadina y testosterona", "Megestrol y paroxetina", "Domperidona y rivastigmina"], "k": 0, "a": "Ciproheptadina y megestrol", "w": "Confirmado en Andy Notas ✔ (p. 69)", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g12-260", "q": "¿Cuáles son las causas psicológicas frecuentes de la anorexia senil?", "x": 3, "o": ["Ansiedad y trastorno bipolar", "Demencia, depresión y duelo", "Alcoholismo y abuso de sustancias", "Depresión y trastorno de la alimentación"], "k": 1, "a": "Demencia, depresión y duelo", "w": "Confirmado en Andy Notas ✔ (p. 69)", "f": "Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, {"id": "g12-261", "q": "Causa social frecuente de anorexia senil:", "x": 2, "o": ["Falta (necesidad) de ayuda para comprar o preparar alimentos", "Hipogonadismo", "Demencia", "Depresión"], "k": 0, "a": "Falta (necesidad) de ayuda para comprar o preparar alimentos", "w": "Confirmado en Andy Notas ✔ (p. 69) — Factores sociales: pobreza y necesidad de ayuda para comprar o preparar alimentos.", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g12-262", "q": "¿Cuál de las siguientes se usa como droga orexigénica?", "x": 2, "o": ["Ciproheptadina", "Fentermina", "Fluoxetina", "Metformina"], "k": 0, "a": "Ciproheptadina", "w": "Confirmado en Andy Notas ✔ (p. 69)", "f": "Ene-Jun 2020 (incl. versión COVID «-1»), 2017 (recuerdos, incl. junio 2017)"}]}, {"n": 13, "titulo": "Dolor", "items": [{"id": "g13-263", "q": "El enunciado \"pérdida irregular de la percepción táctil en esta distribución y zonas de dolor provocadas por un cepillado leve\" corresponde a:", "x": 5, "o": ["Dolor neuropático", "Dolor somático", "Hiperalgesia / alodinia", "Dolor por compromiso vascular"], "k": 2, "a": "Hiperalgesia / alodinia", "w": "Confirmado en GPC IMSS-441-11 con matiz — La GPC describe el dolor neuropático con \"respuesta anormal a estímulos (alodinia e hiperpatía)\".", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c1"}, {"id": "g13-264", "q": "De acuerdo a su temporalidad, ¿cómo clasificaría la sintomatología del dolor?", "x": 3, "o": ["Agudo", "Subagudo", "Crónico", "Ninguna de las anteriores"], "k": 2, "a": "Crónico", "w": "Confirmado en Andy Notas ✔ (p. 74) — Crónico >3 meses (12 semanas).", "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c1"}, {"id": "g13-265", "q": "¿En qué fase cataloga al paciente?", "x": 3, "o": ["Pródromo", "Curación", "Herpes zóster agudo", "Neuralgia postherpética"], "k": 3, "a": "Neuralgia postherpética", "w": "Confirmado en Andy Notas ✔ (p. 74)", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g13-c1"}, {"id": "g13-266", "q": "Según el dermatoma descrito, ¿dónde se localiza el dolor?", "x": 2, "o": ["Cervical", "Lumbar", "Sacro", "Nivel intercostal derecho"], "k": 3, "a": "Nivel intercostal derecho", "w": "No viene en tus documentos — Los dermatomas no vienen en tus documentos; se dejó la clave.", "nt": "Nota: ⚠ Dudosa: el caso dice T10 (nivel del ombligo) y en 2020 \"área de la tetilla\" (T4); se contradice. \"Intercostal derecho\" es la respuesta más segura.", "d": 1, "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g13-c1"}, {"id": "g13-267", "q": "¿Cuál es el esquema terapéutico indicado?", "x": 2, "o": ["Paracetamol 500 mg c/8 h + ibuprofeno 400 mg c/12 h", "Tramadol 100 mg c/8 h + ibuprofeno 800 mg c/12 h", "Pregabalina 75 mg c/24 h + tramadol 25 mg c/12 h", "Ninguna de las anteriores"], "k": 2, "a": "Pregabalina 75 mg c/24 h + tramadol 25 mg c/12 h", "w": "Confirmado en Andy Notas ✔ (p. 77) — Neuromoduladores (pregabalina) de primera línea; opioides en casos resistentes. Es la clave del alumno de 2020; en Nov 2025 se recordó \"pregabalina\".", "f": "Noviembre 2025, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c1"}, {"id": "g13-268", "q": "De acuerdo con su intensidad, ¿cómo clasifica su dolor?", "x": 1, "o": ["Moderado", "Leve", "Severo", "No clasificable"], "k": 2, "a": "Severo", "w": "Confirmado en Andy Notas con matiz (p. 76) — El caso lo describe como \"intenso\" (sin EVA numérica); EVA 7-10 = severo.", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)", "c": "g13-c1"}, {"id": "g13-269", "q": "Según el dermatoma descrito (versión 2020), ¿dónde describiría la localización del dolor?", "x": 1, "o": ["T3", "T4", "T5", "T6"], "k": 1, "a": "T4", "w": "No viene en tus documentos — Se dejó la clave marcada (la tetilla corresponde a T4).", "nt": "Nota: ⚠ Dudosa: el caso de 2020 menciona tanto T10 como la tetilla (T4).", "d": 1, "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c1"}, {"id": "g13-270", "q": "Tipo de dolor:", "x": 1, "o": ["Nociceptivo visceral", "Nociceptivo somático", "Central", "Neuropático periférico"], "k": 3, "a": "Neuropático periférico", "w": "Confirmado en Andy Notas con matiz (p. 74) — La neuralgia postherpética es ejemplo de dolor neuropático.", "r": 1, "f": "Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g13-c1"}, {"id": "g13-271", "q": "¿Qué neurotransmisores están principalmente involucrados en la generación del dolor de la neuralgia postherpética?", "x": 1, "o": ["Glutamato y sustancia P", "Acetilcolina y dopamina", "GABA y encefalinas", "Neurocalcitonina y AMP cíclico"], "k": 0, "a": "Glutamato y sustancia P", "w": "No viene en tus documentos — Clave del alumno de la versión resuelta de 2020.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c1"}, {"id": "g13-272", "q": "¿A cuál de los siguientes trastornos se asocia más frecuentemente este cuadro?", "x": 5, "o": ["Hiperlipidemias", "Diabetes mellitus", "Enfermedades autoinmunes", "Antecedente de varicela o herpes zóster"], "k": 1, "a": "Diabetes mellitus", "w": "Confirmado en Andy Notas ✔ (p. 73) — La neuropatía diabética es la causa n.º 1 de dolor crónico.", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c2"}, {"id": "g13-273", "q": "Según el tipo de dolor, ¿cuál escala es la más adecuada?", "x": 5, "o": ["DN4", "Test de HADS", "Escala de LANSS", "Campbell"], "k": 0, "a": "DN4", "w": "No viene en tus documentos — El DN4 no viene en tus documentos; se dejó la clave.", "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c2"}, {"id": "g13-274", "q": "Según su sospecha clínica, ¿qué estudio es necesario para el diagnóstico?", "x": 3, "o": ["Perfil de lípidos", "Doppler de miembros inferiores", "Angiografía", "Velocidad de conducción nerviosa (de miembros inferiores)"], "k": 3, "a": "Velocidad de conducción nerviosa (de miembros inferiores)", "w": "No viene en tus documentos — Se dejó la clave.", "r": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g13-c2"}, {"id": "g13-275", "q": "Según su patogenia, ¿cuál es lo correcto?", "x": 3, "o": ["Es secundario a compresión de raíces nerviosas en la médula espinal", "Hay pérdida progresiva y muerte de las fibras largas que inervan los segmentos distales", "Produce hipotermia sobre el centro termorregulador del hipotálamo", "Hay desmielinización progresiva de fibras motoras y sensitivas distales"], "k": 3, "a": "Hay desmielinización progresiva de fibras motoras y sensitivas distales", "w": "No viene en tus documentos — Ni en las GPC consultadas; se dejó la clave de 2023-2025.", "nt": "Nota: ⚠ Dudosa (opinión, sin fuente verificada): la neuropatía diabética es principalmente axonal y dependiente de la longitud de la fibra (más cercana a la 2.ª opción). Para el examen se dejó la clave reciente.", "d": 1, "f": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023", "c": "g13-c2"}, {"id": "g13-276", "q": "Según su intensidad, ¿cómo se clasificaría el dolor?", "x": 3, "o": ["Leve", "Moderado", "Severo", "No hay información suficiente"], "k": 1, "a": "Moderado", "w": "Confirmado en Andy Notas ✔ (p. 76) — EVA 4-6 = moderado.", "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c2"}, {"id": "g13-277", "q": "¿Cuáles de los siguientes medicamentos son tratamientos útiles?", "x": 2, "o": ["Solo AINE", "Morfina y diazepam", "Tramadol, pregabalina y duloxetina (en 2023: duloxetina, tramadol y amitriptilina)", "Paracetamol e ibuprofeno"], "k": 2, "a": "Tramadol, pregabalina y duloxetina (en 2023: duloxetina, tramadol y amitriptilina)", "w": "Confirmado en Andy Notas ✔ (p. 77) — Neuromoduladores, ISRN (duloxetina) y opioides en casos resistentes.", "r": 1, "f": "Ordinario 01 nov 2024 (revisión), Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g13-c2"}, {"id": "g13-278", "q": "Según su sospecha clínica (versión 2020), ¿qué estudios de gabinete son necesarios para el diagnóstico?", "x": 1, "o": ["Perfil de lípidos", "Glucosa en ayuno y hemoglobina glucosilada", "Ecografía Doppler de miembros inferiores", "Angiografía de miembros inferiores"], "k": 1, "a": "Glucosa en ayuno y hemoglobina glucosilada", "w": "Confirmado en Andy Notas con matiz (p. 73) — Clave del alumno: busca la diabetes, causa n.º 1 de neuropatía dolorosa crónica. En 2023-2025 la clave fue velocidad de conducción nerviosa.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c2"}, {"id": "g13-279", "q": "Según su patogenia (versión 2020), ¿cuál es lo correcto?", "x": 1, "o": ["Es secundario a compresión de raíces nerviosas en la médula espinal", "Hay pérdida progresiva y muerte de las fibras largas que inervan los segmentos distales", "Produce hipotermia sobre el centro termorregulador del hipotálamo", "Hay desmielinización progresiva de fibras motoras y sensitivas distales"], "k": 1, "a": "Hay pérdida progresiva y muerte de las fibras largas que inervan los segmentos distales", "w": "No viene en tus documentos — Clave del alumno en 2020 (él mismo dudaba entre esta y la desmielinización, que es la clave de 2023-2025).", "nt": "Nota: ⚠ Dudosa: las claves cambian entre años (ver la versión 2023-2025).", "d": 1, "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c2"}, {"id": "g13-280", "q": "Según su temporalidad, ¿cómo se clasifica el dolor?", "x": 1, "o": ["Agudo", "Subagudo", "Crónico", "No clasificable"], "k": 2, "a": "Crónico", "w": "Confirmado en Andy Notas ✔ (p. 74) — 18 meses (>3 meses).", "r": 1, "f": "Noviembre 2025 · opciones reconstruidas (el original no las conservó)", "c": "g13-c2"}, {"id": "g13-281", "q": "¿Cuál de los siguientes esquemas son tratamientos de primera elección?", "x": 1, "o": ["Gabapentina, amitriptilina y venlafaxina", "Duloxetina, tramadol y amitriptilina", "Pregabalina, duloxetina y lidocaína", "Gabapentina, venlafaxina y morfina"], "k": 0, "a": "Gabapentina, amitriptilina y venlafaxina", "w": "Confirmado en GPC SSA-010-08 ✔ — La GPC de dolor por neuropatía diabética incluye tricíclicos (amitriptilina), ISRN (duloxetina, venlafaxina) y gabapentinoides (gabapentina, pregabalina). Es la clave del alumno.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c2"}, {"id": "g13-282", "q": "Señale lo correcto respecto a la evaluación del dolor en pacientes geriátricos:", "x": 2, "o": ["Considerar en este caso el aumento del umbral del dolor secundario al envejecimiento", "Evaluar otros factores que puedan influir en el dolor: físicos, psicológicos, sociales, culturales y espirituales", "Se debe evaluar solo el dolor que motiva la consulta", "Todas las anteriores"], "k": 1, "a": "Evaluar otros factores que puedan influir en el dolor: físicos, psicológicos, sociales, culturales y espirituales", "w": "CORREGIDO según Andy Notas (p. 75) — La clave de Mayo 2023 fue \"todas las anteriores\", pero en tus notas solo la 2.ª es correcta: no se evalúa solo el dolor que motiva la consulta.", "f": "Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c3"}, {"id": "g13-283", "q": "¿Cuáles son las principales causas de dolor en pacientes de la tercera edad?", "x": 2, "o": ["Fibromialgia e inflamación aguda", "Artritis y neuralgia", "Estenosis espinal y neuropatía diabética", "Lumbalgia y dolor post-EVC"], "k": 1, "a": "Artritis y neuralgia", "w": "Confirmado en Andy Notas ✔ (p. 74) — Principales: artritis, neuralgia y lumbalgia.", "f": "Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c3"}, {"id": "g13-284", "q": "¿Qué pacientes son candidatos a procedimientos intervencionistas?", "x": 2, "o": ["Pacientes con dolor crónico de curso evolutivo prolongado que no responden a los tratamientos convencionales", "Pacientes con dolor EVA >7/10", "Pacientes geriátricos con enfermedades terminales", "Pacientes geriátricos con cualquier enfermedad de curso prolongado"], "k": 0, "a": "Pacientes con dolor crónico de curso evolutivo prolongado que no responden a los tratamientos convencionales", "w": "Confirmado en Andy Notas con matiz (p. 77) — El 4.º paso (algología) es para quien no mejora con medicamentos.", "f": "Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c3"}, {"id": "g13-285", "q": "En los pacientes geriátricos, ¿cuáles son los factores que disminuyen el umbral del dolor?", "x": 1, "o": ["Ansiedad", "Depresión", "Mejoría clínica de los síntomas", "A y B"], "k": 3, "a": "A y B", "w": "Confirmado en Andy Notas ✔ (p. 75)", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c3"}, {"id": "g13-286", "q": "Factor que AUMENTA el umbral del dolor:", "x": 1, "o": ["Depresión", "Aburrimiento", "Insomnio", "Mejoría clínica de los síntomas"], "k": 3, "a": "Mejoría clínica de los síntomas", "w": "Confirmado en Andy Notas con matiz (p. 75) — Pregunta reconstruida (solo se recordó la respuesta).", "r": 1, "f": "Mayo 2023 · opciones reconstruidas (el original no las conservó)", "c": "g13-c3"}, {"id": "g13-287", "q": "Con relación al uso de analgésicos en general, señale lo correcto:", "x": 5, "o": ["Administrar los analgésicos siempre a horas fijas", "El dolor crónico no requiere terapia preventiva", "La supervivencia prevista determina la potencia del analgésico", "El uso de placebos está justificado por el alto porcentaje de simuladores"], "k": 0, "a": "Administrar los analgésicos siempre a horas fijas", "w": "Confirmado en las Diapositivas de clase ✔ (p. 482) — \"Analgésicos siempre a horas fijas\"; el dolor crónico necesita terapia preventiva y nunca se usan placebos.", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)", "c": "g13-c4"}, {"id": "g13-288", "q": "En cuanto al tratamiento analgésico que toma actualmente, corresponde a:", "x": 2, "o": ["Opioide menor y adyuvante", "Paracetamol y opioide menor", "Paracetamol y adyuvante", "AINE y opioide mayor"], "k": 3, "a": "AINE y opioide mayor", "w": "Confirmado en Andy Notas ✔ (p. 77) — La buprenorfina es opioide mayor.", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g13-c4"}, {"id": "g13-289", "q": "Esto correspondería al siguiente escalón de la escala analgésica:", "x": 2, "o": ["Cuarto escalón", "Tercer escalón", "Segundo escalón", "Primer escalón"], "k": 1, "a": "Tercer escalón", "w": "Confirmado en Andy Notas ✔ (p. 76) — En 2022 se discutió también el cuarto escalón por la redacción.", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g13-c4"}, {"id": "g13-290", "q": "La valoración geriátrica y el IPAS le permiten identificar 2 factores que disminuyen el umbral del dolor:", "x": 2, "o": ["Dependencia parcial", "Depresión e insomnio", "Confusión y ansiedad", "Desnutrición y lesión vertebral"], "k": 1, "a": "Depresión e insomnio", "w": "Confirmado en Andy Notas ✔ (p. 75)", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g13-c4"}, {"id": "g13-291", "q": "Su recomendación en este momento sería:", "x": 2, "o": ["Cambiar a paracetamol", "Añadir un adyuvante para el dolor", "Suspender el opioide", "Reposo absoluto"], "k": 1, "a": "Añadir un adyuvante para el dolor", "w": "Confirmado en Andy Notas con matiz (p. 76) — Los adyuvantes se pueden sumar en cualquier escalón. En 2022 se discutió también el bloqueo.", "r": 1, "f": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g13-c4"}, {"id": "g13-292", "q": "¿Cuál es el diagnóstico presuntivo?", "x": 3, "o": ["Cefalea tensional", "Sinusitis", "Migraña", "Tumor cerebral"], "k": 0, "a": "Cefalea tensional", "w": "Confirmado en GPC IMSS-047-08 con matiz — La cefalea tensional se diagnostica clínicamente, con examen neurológico normal. Se discutió también migraña.", "nt": "Nota: ⚠ Dudosa (opinión, sin fuente verificada): cefalea nueva en mayor de 50 años con dolor temporal que no cede es dato de alarma; habría que descartar arteritis de células gigantes (VSG/PCR) y pedir neuroimagen. El sumatriptán no trata la cefalea tensional y se evita en ancianos con riesgo cardiovascular.", "d": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos)", "c": "g13-c5"}, {"id": "g13-293", "q": "¿Qué estudio realizaría para confirmar el diagnóstico?", "x": 3, "o": ["TAC", "Radiografía de senos paranasales", "ECG", "No se requieren más estudios"], "k": 3, "a": "No se requieren más estudios", "w": "Confirmado en GPC IMSS-047-08 ✔ — \"Laboratorios e imagenología no justificados, únicamente considerarlos en caso de datos de alarma\".", "nt": "Nota: ⚠ Dudosa (opinión): por la edad mayor de 50 años y el dolor temporal nuevo, yo descartaría arteritis de células gigantes (VSG/PCR) y pediría imagen.", "d": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos)", "c": "g13-c5"}, {"id": "g13-294", "q": "¿Cuál es el tratamiento? a) Sumatriptán b) Cirugía y radioterapia c) Tratamiento de senos paranasales", "x": 3, "s": 1, "a": "Sin clave en los exámenes (ver la nota).", "w": "Sin clave — La GPC IMSS-047-08 trata la cefalea tensional con paracetamol, aspirina o AINE (de preferencia ibuprofeno) y profilaxis con amitriptilina; no recomienda triptanes. Ninguna de las opciones recordadas coincide.", "f": "Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos)", "c": "g13-c5"}, {"id": "g13-295", "q": "¿Cuál sería la conducta a seguir?", "x": 1, "o": ["Observación", "Iniciar antidepresivo", "Referir a neurocirugía", "Antibiótico"], "k": 1, "a": "Iniciar antidepresivo", "w": "Confirmado en GPC IMSS-047-08 con matiz — La GPC recomienda amitriptilina como profilaxis en cefalea tensional frecuente o crónica; además el paciente tiene ideas de muerte.", "nt": "Nota: ⚠ Dudosa: la clave quedó sin confirmar en Ago-Dic 2022.", "d": 1, "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)", "c": "g13-c5"}, {"id": "g13-296", "q": "El tratamiento que toma corresponde a:", "x": 3, "o": ["Opioide mayor", "Solo adyuvante", "Analgésico no opioide (AINE/paracetamol) y opioide menor", "Bloqueo"], "k": 2, "a": "Analgésico no opioide (AINE/paracetamol) y opioide menor", "w": "Confirmado en Andy Notas ✔ (p. 77)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)", "c": "g13-c6"}, {"id": "g13-297", "q": "Pertenece al escalón:", "x": 3, "o": ["Tercer escalón", "Segundo escalón", "Cuarto escalón", "Primer escalón"], "k": 1, "a": "Segundo escalón", "w": "Confirmado en Andy Notas ✔ (p. 76)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)", "c": "g13-c6"}, {"id": "g13-298", "q": "Siguiente paso del tratamiento:", "x": 3, "o": ["Suspender analgésicos", "Cirugía", "Regresar al primer escalón", "Tercer escalón (opioide fuerte)"], "k": 3, "a": "Tercer escalón (opioide fuerte)", "w": "Confirmado en Andy Notas ✔ (p. 76)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos) · opciones reconstruidas (el original no las conservó)", "c": "g13-c6"}, {"id": "g13-299", "q": "La combinación analgésica que recibe consiste en:", "x": 1, "o": ["Paracetamol y opioide menor", "Opioide menor y adyuvante", "Paracetamol y adyuvante", "Opioide mayor y adyuvante"], "k": 3, "a": "Opioide mayor y adyuvante", "w": "Confirmado en Andy Notas ✔ (p. 77)", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c7"}, {"id": "g13-300", "q": "Correspondería actualmente al escalón analgésico:", "x": 1, "o": ["Primer escalón", "Tercer escalón", "Segundo escalón", "Cuarto escalón"], "k": 1, "a": "Tercer escalón", "w": "Confirmado en Andy Notas ✔ (p. 76)", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c7"}, {"id": "g13-301", "q": "La evaluación permitió identificar dos factores que disminuyen el umbral del dolor:", "x": 1, "o": ["Dependencia parcial en actividades básicas e instrumentales", "Depresión e insomnio", "Confusión y ansiedad", "Desnutrición y lesión vertebral"], "k": 1, "a": "Depresión e insomnio", "w": "Confirmado en Andy Notas ✔ (p. 75)", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c7"}, {"id": "g13-302", "q": "Su recomendación en este momento consiste en:", "x": 1, "o": ["Oxcarbazepina y terapia física", "Inmovilización y aumentar la dosis de los analgésicos actuales", "Terapia alternativa", "Sertralina, triazolam y terapia física"], "k": 2, "a": "Terapia alternativa", "w": "Confirmado en Andy Notas con matiz (p. 76) — Tus notas incluyen musicoterapia, terapia física y psicológica como tratamiento no farmacológico.", "f": "Ene-Jun 2020 (incl. versión COVID «-1»)", "c": "g13-c7"}, {"id": "g13-303", "q": "¿Cuál es la definición de dolor de la International Association for the Study of Pain (IASP)?", "x": 5, "o": ["Experiencia sensorial y emocional desagradable, con lesión real o potencial de los tejidos", "Sensación iniciada por una lesión primaria o disfunción del sistema nervioso central o periférico", "Sensación que se produce por lesión en la terminación de una fibra nerviosa", "Sensación propagada con origen a distancia con fibras nerviosas indemnes"], "k": 0, "a": "Experiencia sensorial y emocional desagradable, con lesión real o potencial de los tejidos", "w": "Confirmado en Andy Notas ✔ (p. 73)", "f": "Ene-Jun 2024 (revisión), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), 2017 (recuerdos, incl. junio 2017), Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012"}, {"id": "g13-304", "q": "Dolor de rodilla moderado a intenso con incapacidad para la marcha; el paracetamol ya no funciona. ¿Qué indica?", "x": 3, "o": ["Reposo absoluto", "AINE + opioide menor", "Morfina", "Infiltración inmediata"], "k": 1, "a": "AINE + opioide menor", "w": "Confirmado en Andy Notas ✔ (p. 76) — Dolor moderado (EVA 4-6) = segundo escalón.", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Diciembre 2018 (recuerdos), Ene-Jun 2015, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g13-305", "q": "El dolor en general es transmitido por qué tipo de fibras:", "x": 3, "o": ["Fibras motoras", "Fibras B", "Fibras A y C", "Solo fibras C"], "k": 2, "a": "Fibras A y C", "w": "No viene en tus documentos — Se dejó la clave.", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015, Examen 2012 · opciones reconstruidas (el original no las conservó)"}, {"id": "g13-306", "q": "Escala que evalúa el dolor en pacientes con demencia:", "x": 1, "o": ["PAINAD", "McGill", "EVA", "DN4"], "k": 0, "a": "PAINAD", "w": "Confirmado en Andy Notas ✔ (p. 76) — Observa 3-5 min: respiración, vocalización, expresión facial, lenguaje corporal y consolabilidad.", "r": 1, "f": "Ene-Jun 2024 (revisión) · opciones reconstruidas (el original no las conservó)"}, {"id": "g13-307", "q": "Síndrome doloroso geriátrico más frecuente:", "x": 1, "o": ["Lumbalgia", "Osteoartrosis", "Cefalea", "Neuralgia postherpética"], "k": 1, "a": "Osteoartrosis", "w": "Confirmado en Andy Notas con matiz (p. 73) — Se discutió: Andy señala lo musculoesquelético lumbar como la causa más común en la comunidad y lo reumatológico en institucionalizados.", "r": 1, "f": "Ago-Dic 2022 (nov 2022 + lectura de examen) · opciones reconstruidas (el original no las conservó)"}, {"id": "g13-308", "q": "Primer escalón de la escalera analgésica de la OMS:", "x": 2, "o": ["Morfina", "Paracetamol (no opioide ± adyuvante)", "Tramadol", "Bloqueo nervioso"], "k": 1, "a": "Paracetamol (no opioide ± adyuvante)", "w": "Confirmado en Andy Notas ✔ (p. 76)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g13-309", "q": "Segundo escalón de la OMS para el manejo del dolor:", "x": 2, "o": ["Opioides débiles (± no opioide ± adyuvante)", "Solo AINE", "Intervención quirúrgica", "Opioides fuertes"], "k": 0, "a": "Opioides débiles (± no opioide ± adyuvante)", "w": "Confirmado en Andy Notas ✔ (p. 76)", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015 · opciones reconstruidas (el original no las conservó)"}, {"id": "g13-310", "q": "Porcentaje de casos en que el dolor se puede controlar con tratamiento:", "x": 1, "o": ["90 %", "10 %", "30 %", "50 %"], "k": 0, "a": "90 %", "w": "Confirmado en las Diapositivas de clase ✔ (p. 490)", "r": 1, "f": "Diciembre 2018 (recuerdos) · opciones reconstruidas (el original no las conservó)"}]}, {"n": 14, "titulo": "Rehabilitación", "items": [{"id": "g14-311", "q": "¿Qué le haría?", "x": 1, "o": ["Silla de ruedas permanente", "Rehabilitación progresiva: movilidad en cama (decúbitos laterales) → sedestación → bipedestación → marcha", "Sujeción", "Reposo absoluto"], "k": 1, "a": "Rehabilitación progresiva: movilidad en cama (decúbitos laterales) → sedestación → bipedestación → marcha", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 12, diapo 20) — Secuencia: «Movilidad en cama → sedestación en cama → bipedestación» (→ marcha, diapo 24); plan «individualizado, progresivo, sin sobrepasar la capacidad funcional» (diapo 19). También en Andy Notas (p. 81).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)", "c": "g14-c1"}, {"id": "g14-312", "q": "¿Qué tipo de prevención es?", "x": 1, "o": ["Primaria", "Cuaternaria", "Secundaria", "Terciaria"], "k": 3, "a": "Terciaria", "w": "Confirmado en Andy Notas con matiz (p. 72) — Tus notas ubican la terapia física para limitar la discapacidad como prevención terciaria.", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)", "c": "g14-c1"}, {"id": "g14-313", "q": "Contraindicación en la movilización (rehabilitación) de un paciente:", "x": 3, "o": ["Edad mayor de 80 años", "Pérdida (extrema) de la fuerza muscular", "Uso de andador", "Diabetes controlada"], "k": 1, "a": "Pérdida (extrema) de la fuerza muscular", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 12, diapo 29) — Contraindicaciones: «Deterioro severo del equilibrio o debilidad muscular extrema». También en Andy Notas (p. 82).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021), Ene-Jun 2015, Recopilación 26 nov 2013 · opciones reconstruidas (el original no las conservó)"}, {"id": "g14-314", "q": "Son contraindicaciones de la rehabilitación:", "x": 1, "o": ["Osteoartrosis crónica", "Fase aguda de la artritis reumatoide, dolor no controlado, demencia avanzada, falta de motivación y riesgo de agravar la patología de base", "Hipertensión controlada", "Edad avanzada"], "k": 1, "a": "Fase aguda de la artritis reumatoide, dolor no controlado, demencia avanzada, falta de motivación y riesgo de agravar la patología de base", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 12, diapo 29) — «Fase aguda de artritis reumatoide · Deterioro severo del equilibrio o debilidad muscular extrema (… demencia en fases avanzadas) · Dolor no controlado con la movilización · Falta absoluta de motivación». También en Andy Notas (p. 82).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)"}, {"id": "g14-315", "q": "Inmovilidad en la que hay movilidad parcial:", "x": 1, "o": ["Absoluta", "Relativa", "Aguda", "Crónica"], "k": 1, "a": "Relativa", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 12, diapo 3) — «Inmovilidad relativa: es la inmovilidad en la que hay movilidad parcial». También en Andy Notas (p. 78).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)"}, {"id": "g14-316", "q": "Duración de la inmovilidad aguda o terapéutica:", "x": 1, "o": ["1 año", "Menos de 3 días", "Más de 3 meses", "6 meses"], "k": 1, "a": "Menos de 3 días", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 12, diapo 3) — «Inmovilidad aguda: <3 días “terapéutica” o mórbida»; la crónica, «>3 meses». También en Andy Notas (p. 78).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó)"}, {"id": "g14-317", "q": "Exploración de la movilidad en un paciente con inmovilidad absoluta:", "x": 1, "o": ["Prueba de 6 minutos", "Time Up and Go", "Tinetti completo", "Girar en la cama, incorporarse a la posición sentada y luego a bipedestación"], "k": 3, "a": "Girar en la cama, incorporarse a la posición sentada y luego a bipedestación", "w": "★ Confirmado en Diapositivas 2026 ✔ (Tema 12, diapo 17) — «Movilidad en la cama: capacidad de girar e incorporarse a la posición sentado y posteriormente, a bipedestación». También en Andy Notas (p. 80).", "r": 1, "f": "Recopilación por temas (sin fecha, ≈2021) · opciones reconstruidas (el original no las conservó) Anexo. Cambios hechos con las Diapositivas 2026 Preguntas cuya clave se cambió porque las diapositivas más recientes de la materia dicen otra cosa. Las demás preguntas revisadas con las diapositivas conservaron su clave y ahora citan la diapositiva en su justificación. # Tema Pregunta Nueva respuesta y motivo 41 3 ¿Cuál de los siguientes medicamentos conlleva un riesgo significativo de caídas? Clonazepam. La clave era clorfenamina. Según la diapositiva, benzodiazepinas = «delirium, caídas, fracturas, deterioro psicomotor», y anticolinérgicos = «confusión, retención urinaria, estreñimiento, visión borrosa». El fármaco de caídas es el clonazepam (Tema 2, diapo 10: caídas por diazepam). 109 6 ¿Cuál de las siguientes capacidades cognoscitivas se encuentra alterada? Velocidad de procesamiento. La clave era atención. Según la diapositiva, en la depresión la atención «suele preservarse» (está «marcadamente alterada» en el delirium); lo cognitivo de la depresión es «lentitud, indecisión, concentración» (Tema 5, diapo 5), que corresponde a la velocidad de procesamiento."}]}], "total": 317, "casos": {"g1-c1": {"v": "En 2010 se realizó un estudio demográfico en un centro de salud de la colonia Roma, Monterrey: envejecimiento poblacional 10.5 %, tasa de dependencia 4.1, natalidad 15 %, mortalidad 9 %, HTA 30 %, DM 22 % y discapacidad física 18 %. El centro promovió programas de prevención y capacitación de cuidadores informales.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g2-c1": {"v": "Masculino de 78 años con Parkinson de 8 años (neurología), osteoartrosis espinal (traumatólogo privado) e HPB asintomática. Tras una caída leve, en su centro de salud le suspendieron súbitamente levodopa/carbidopa por no mostrar signos extrapiramidales; después está bradicinético, con facies inexpresiva y temblor de reposo.", "ap": "Recopilación 26 nov 2013, Examen 2012"}, "g3-c1": {"v": "Femenina de 73 años, previamente sana, con insomnio intermedio de 3 meses. MMSE 28, GDS 8, Katz 5, Lawton-Brody 4, TUG 12 s; tristeza, anhedonia y llanto fácil. Se inicia escitalopram y a los 14 días mejora: MMSE 30, GDS 4, Katz 5, Lawton-Brody 5, TUG 12 s.", "ap": "Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, "g3-c2": {"v": "Mujer de 80 años, viuda, vive sola. Insomnio, osteoporosis, HTA, rinitis alérgica y OA. Toma clonazepam 1 mg/24 h, metoprolol, enalapril, paracetamol, calcio, aspirina y clorfenamina PRN. Hace un año inició hiporexia, pérdida de peso, anhedonia, insomnio intermedio y ansiedad leve; niega tristeza. GDS 7, MMSE 24 (memoria, cálculo y orientación en fecha), Katz 4, Lawton-Brody 4, TUG 21 s. IMC 26, soplo sistólico aórtico II/VI, borde hepático palpable 2 cm, crepitantes secos escasos y xifoescoliosis.", "ap": "26 may 2022 (Examsoft)"}, "g3-c3": {"v": "Paciente de 83 años, débil y cansado desde hace 2 meses; HTA y angina estable. Dos meses de cansancio, hiporexia, pérdida de interés, periodos de confusión y desorientación; tuvo fiebre con urgencia e incontinencia urinaria tratada con ciprofloxacino solo 5 dosis. Se postra en cama; el médico familiar dice que por su edad \"es posible que fallezca sin importar las intervenciones\". MMSE 23, GDS 5, Katz 2, Lawton 0.", "ap": "Recopilación 26 nov 2013, Examen 2012"}, "g4-c1": {"v": "Masculino de 88 años sin antecedentes, en valoración anual. Madre falleció a los 98 años y padre a los 92. Es presidente del consejo de la empresa que creó en 1995 y socio activo de un club rotario. Camina 10 min diarios; dieta casera alta en fibra y proteínas, baja en carbohidratos, sin grasas, de 1450 kcal; toma 10 vasos de agua al día.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g5-c1": {"v": "Masculino de 69 años con DM, HTA e hipercolesterolemia de larga evolución, traído por su esposa porque sus compañeros de trabajo (guardia de seguridad) notan dificultades para desempeñarse y desorientación desde hace meses; la esposa lo lleva y trae por miedo a que se pierda. Ella hace la mayoría de las actividades del hogar y paga los servicios; él toma sus medicamentos sin supervisión. Katz 6, Lawton-Brody 2, MMSE 23 (memoria reciente y cálculo), GDS 3, CAM 0, TUG 10 s.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, "g5-c2": {"v": "Femenina de 80 años con HTA, DM y trastorno depresivo, tratada con metoprolol 50 mg, metformina 850 mg y paroxetina 20 mg. Olvidos de inicio súbito y 8 meses de evolución, en aumento: olvida eventos recientes, dificultad para seguir indicaciones simples y para nombrar objetos de uso común, para tareas físicas complejas y ocasionalmente desconoce lugares y personas; curso progresivo y deterioro escalonado. Reconoce su problema. Marcha con paso corto y bajo; resto normal.", "ap": "Ago-Dic 2022 (nov 2022 + lectura de examen), Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, "g5-c3": {"v": "Hombre de 84 años con HTA, dislipidemia, insomnio e HPB (losartán, pravastatina, triazolam, terazosina). Por infección respiratoria le indicaron clorfeniramina 4 mg cada 12 h; 4 días después somnolencia, alucinaciones visuales, debilidad, hiporexia, confusión y alteración del lenguaje. Mal hidratado, inatento, lenguaje farfullante, desorientado. Katz 0, Lawton 0, MMSE 7.", "ap": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021)"}, "g5-c4": {"v": "Femenina de 82 años con DM y dislipidemia (metformina y pravastatina), consumo de proteína de 0.5 g/kg. Consciente, con lateropulsión derecha. MMSE 18, GDS 8, Katz 5, Lawton-Brody 5.", "ap": "Ago-Dic 2022 (nov 2022 + lectura de examen)"}, "g5-c5": {"v": "Mujer con olvidos que afectan la preparación de alimentos, cuidados domésticos (alimentos caducados, ropa sin lavar), pago de servicios y citas. Interrogatorio por aparatos negativo. MMSE 21, GDS 5, Lawton-Brody 4, Katz 4.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g5-c6": {"v": "Paciente (tratada con metoprolol, metformina y paroxetina) con olvidos de 14 días que han aumentado; olvida eventos recientes, dificultad para planear tareas y para nombrar objetos, desconoce ocasionalmente lugares y personas, de instalación insidiosa y curso progresivo, con gran repercusión funcional. No reconoce su problema. Marcha con discreta lateropulsión derecha y fuerza 3/5 proximal en miembro inferior derecho.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g5-c7": {"v": "Paciente de 86 años con olvidos de 18 meses (olvida compromisos y citas), sin repetir cosas ni perder objetos; familia lo confirma. Atenolol e ibuprofeno PRN. MMSE 28, escala de depresión 4, Katz 6, Lawton-Brody 7, velocidad de marcha 0.9 m/s.", "ap": "Recopilación 26 nov 2013, Examen 2012"}, "g6-c1": {"v": "Femenino de 72 años, comerciante, llevada a una campaña de memoria por olvidos desde hace 4 meses, tras cerrar su tienda. Olvidos ocasionales de fechas importantes, no pone atención; hipersomnia, tristeza, falta de energía, anhedonia e hiporexia con ropa más holgada. Vive sola y realiza todas las ABVD y AIVD. AINE ocasionales por OA de rodilla. Peso de 71 a 68.5 kg. MMSE 27/30 (1 error en memoria y 2 en orientación en tiempo), GDS Yesavage 8/15 (en 2020: MMSE 28 y GDS 12).", "ap": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g6-c2": {"v": "Femenina de 76-81 años con HTA y osteoartritis, con 8 meses de ánimo bajo, llanto, pérdida de 5 kg, minusvalía, culpa, desesperanza e ideas de muerte sin ideación suicida; desde hace 2 meses alucinaciones (su padre muerto le advierte que le quieren robar), soliloquios y actitudes paranoides. MMSE 25/30; autónoma para ABVD y AIVD.", "ap": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen), Diciembre 2018 (recuerdos), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos), Ene-Jun 2015"}, "g6-c3": {"v": "Paciente de 82 años con HTA y DM (enalapril), con 30 días de tristeza, anhedonia, debilidad, hiporexia e insomnio. Marcha con base de sustentación amplia, elevación del pie de unos 15 cm con un pie rebasando ligeramente al otro, braceo disminuido, sin extrapiramidalismo. GDS 12, MMSE 18, Katz 6, Lawton-Brody 6, TUG 8 s.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión)"}, "g6-c4": {"v": "Masculino de 73 años con cansancio crónico, apatía, pérdida del apetito, despertares nocturnos e hipersomnia diurna y aislamiento social. Niega llanto y tristeza; solo indiferencia ante lo que antes le era placentero. Sin síntomas ansiosos ni psicóticos. Cuadro de 1.5 años con exacerbación en los últimos 6 meses; sin episodios depresivos previos.", "ap": "Ago-Dic 2022 (nov 2022 + lectura de examen)"}, "g6-c5": {"v": "Femenino de 75 años, viuda, vive sola. HAS (losartán y metoprolol), estreñimiento y despertares nocturnos sin mejoría con melatonina. Seis meses de tristeza, llanto fácil, desesperanza, ideas de muerte sin plan suicida, hiporexia, ansiedad discreta y anhedonia. Desorientada en tiempo e inatenta. MMSE 24 (memoria y orientación en tiempo), GDS 7, Katz 4, Lawton-Brody 4, TUG 14 s.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g6-c6": {"v": "Masculino de 82 años con 4 años de sueño poco profundo y despertares frecuentes; no logra dormir de día; falta de concentración, fatiga y apatía. Toma una botella de vino para dormir (funcionó hasta hace 2 meses) y clonazepam 2-4 mg ocasional sin resultado.", "ap": "Recopilación 26 nov 2013, Examen 2012"}, "g7-c1": {"v": "Masculino de 78 años con DM, osteoartrosis y depresión con ansiedad, tratado con enalapril, metoprolol, alprazolam, citalopram y paracetamol con codeína. Caídas y dificultad para la marcha de 2 meses, de instalación paulatina, precedidas de 6 meses de disminución de la funcionalidad. MMSE 22, GDS 4, Katz 3, Lawton-Brody 3, Tinetti 9. Debilidad para la marcha; notable disminución de masa muscular en la cara anterior del muslo y aumento de volumen con crepitación en ambas rodillas.", "ap": "26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, "g7-c2": {"v": "Mujer con caídas frecuentes y alteración de la marcha: HTA desde los 45 años, cataratas, maculopatía y osteoartrosis; toma losartán, hidroclorotiazida, aspirina y paracetamol. Caídas desde hace 18 meses con mareo al incorporarse y tropezones. Olvidos de 3 años. Vive con su hija; pasillos obstruidos e iluminación parcial. TA 115/45 y 90/40 a los 3 minutos de pie. MMSE 24, GDS 4, Katz 5, Lawton 3, TUG 25 s, Tinetti 22.", "ap": "Ene-Jun 2015, Recopilación 26 nov 2013, Examen 2012"}, "g7-c3": {"v": "Paciente de 86 años con caídas (3 preguntas; caso recordado de forma incompleta).", "ap": "Ene-Jun 2024 (revisión)"}, "g7-c4": {"v": "Femenino de 85 años con DM2, AR controlada e insomnio, tratada con metformina, metotrexate, ácido fólico, celecoxib, aspirina y diazepam. Cae de su altura al regresar del baño; refiere marcha insegura. Fuerza 3/5 proximal en miembros inferiores, base de sustentación amplia, longitud del paso variable y paso bajo y corto.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g8-c1": {"v": "Masculino de 78 años con fatiga, debilidad, hiporexia y pérdida de peso de 2 meses. HTA controlada con enalapril e hipercolesterolemia con pravastatina. Katz 4, Lawton 0, GDS 5, MMSE 26; dificultad marcada en las transferencias. Peso 58 kg, talla 1.65 m, marcha lenta de 0.3 m/s, dolor leve a la movilidad de la cadera derecha, soplo aórtico 3/6, pantorrilla 28 cm, prensión 3/5 y ROT disminuidos. Hb 12, albúmina y colesterol normales.", "ap": "Ago-Dic 2022 (nov 2022 + lectura de examen), 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), Diciembre 2018 (recuerdos)"}, "g8-c2": {"v": "Femenina de 79 años con caídas, fractura de cadera y prótesis hace 1 año; tras la hospitalización tuvo 2 caídas más. Usa andador ocasionalmente, desinterés en su persona, consume 1200 kcal/día y evita carnes. Se siente débil, fatigada y se agota fácilmente. Peso 62 kg (habitual 70), pantorrilla 30 cm con escasa masa muscular, prensión 20.4 kg. MMSE 26, GDS 5, Katz 5, Lawton 4, velocidad de marcha 0.4 m/s.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Ene-Jun 2024 (revisión)"}, "g9-c1": {"v": "Masculino de 70 años con DM, HTA e hipercolesterolemia; hace 2 años tuvo un EVC con hemiparesia derecha y desde entonces usa andador dentro de casa. Su esposa refiere que se levanta a orinar al menos 4 veces por la noche y muchas veces no alcanza a llegar, por lo que usa pañal. Toma metformina 850 mg c/12 h, hidroclorotiazida ½ tableta por la noche, pravastatina y aspirina.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2021, Ago-Dic 2020 (+ otra clave)"}, "g9-c2": {"v": "Femenina de 81 años con HTA de 10 años tratada con prazosina 1 mg/día, trastorno depresivo mayor tratado con paroxetina 20 mg y estreñimiento ocasional. Refiere pérdida involuntaria de orina asociada a un fuerte deseo miccional, que ha empeorado su ánimo porque no puede salir de casa. GDS 4, MMSE 28, Katz 4, Lawton 5.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ago-Dic 2020 (+ otra clave)"}, "g9-c3": {"v": "Hombre con depresión en remisión (imipramina 20 mg) e hidroclorotiazida 25 mg, con incontinencia de escasa cantidad y continua de 10 días, que requiere cambio de ropa 3 veces al día; 6 meses de disminución del calibre del chorro, pujo y síndrome disúrico discreto; dolor en hipogastrio con globo vesical palpable.", "ap": "Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos)"}, "g9-c4": {"v": "Masculino de 64-74 años con depresión en remisión tratada con imipramina, más hidroclorotiazida. Incontinencia urinaria de escasa cantidad y continua (cambia de ropa 3 veces al día); refiere disminución del calibre del chorro y pujo; globo vesical palpable.", "ap": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen)"}, "g9-c5": {"v": "Hombre de 78 años con Parkinson avanzado, postrado, con úlcera sacra infectada (caso de úlceras). En el seguimiento tiene incontinencia urinaria constante en el pañal, pesadez hipogástrica y estreñimiento de 5 días sin evacuar.", "ap": "26 may 2022 (Examsoft)"}, "g10-c1": {"v": "Femenino de 74 años, empacadora, con DM2 de 10 años (metformina 850 mg c/12 h, HbA1c 7.5 %). Desde hace 2 meses sigue una dieta keto autoindicada de 1400 kcal. Consulta por debilidad general, marcha lenta y mareos, con 1 caída previa; la ven más delgada y tiene estreñimiento de 4 semanas (evacua cada 7 días). Peso 54 kg, talla 1.61 m, FC 52. Fuerza 4/5, prensión 18 kg, marcha de 24 s en 6 m, pantorrilla 28 cm.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g11-c1": {"v": "Masculino de 60 años con síndrome de Down, extrasístoles ventriculares, EVC hace 2 años y deterioro cognitivo vascular de 1 año. Deterioro funcional progresivo; postrado en cama desde hace 1 año, apático y con somnolencia diurna. Hace 2 semanas apareció una úlcera sacra que, a pesar de los cambios de posición, creció hasta 7 cm, con secreción amarillenta y mal olor. EF: úlcera sacra con exposición de músculo y tendones, borde irregular, fondo necrótico y salida de material purulento.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, 26 may 2022 (Examsoft), Ene-Jun 2021, Ago-Dic 2020 (+ otra clave), Recopilación por temas (sin fecha, ≈2021)"}, "g11-c2": {"v": "Hombre de 78 años con osteoartrosis (paracetamol) y Parkinson avanzado de 18 años (carbidopa/levodopa), postrado desde hace 3 meses. Úlcera sacra de 21 días, progresiva; en los últimos 14 días disfagia, somnolencia e incontinencia urinaria. Temp 38 °C, deshidratación leve, atrofia muscular y contracturas en flexión. Úlcera sacra de 4 cm con fondo blanquecino-amarillo, eritema en bordes y base, escara blanca central de 1 cm y secreción purulenta difusa con hiperemia circundante.", "ap": "26 may 2022 (Examsoft)"}, "g11-c3": {"v": "Masculino de 80 años con tabaquismo intenso y trastorno neurocognitivo mayor vascular avanzado (quetiapina). Hace 4 semanas cayó y se fracturó la cadera (cirugía); egresó hace una semana y sigue en cama. Úlceras por presión en sacro y glúteos: úlcera sacra de 4 cm, bordes irregulares, con daño de la epidermis y exposición de tejido graso, sin infección. Usa pañal por incontinencia urinaria; extremidades atróficas con fuerza disminuida.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g12-c1": {"v": "Masculino residente de una casa de retiro, con síndrome de Down, múltiples infartos cerebrales y deterioro cognitivo mixto. Desde su ingreso tiene anorexia, pérdida de peso y mayor dependencia. Movilidad limitada de la cama al sillón; 4 días sin levantarse (y sin evacuar). Katz 0, Lawton 0, CFS 7, GDS global 100. Rechaza constantemente la alimentación.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023"}, "g12-c2": {"v": "Paciente que no hace ejercicio protocolizado, solo actividad física ocasional, con variaciones en el desempeño físico, hiporexia y síntomas depresivos (caso recordado de forma incompleta).", "ap": "Ene-Jun 2024 (revisión)"}, "g13-c1": {"v": "Paciente de 73 años con DM insulinodependiente, hipercolesterolemia y osteoporosis. Dolor y prurito persistentes en el dermatoma T10 derecho a partir de un herpes zóster comprobado (en 2020: \"un año antes, en el área de la tetilla\"). Dolor urente, intenso y continuo, con paroxismos lancinantes e hipersensibilidad al tacto leve. Cicatrices y excoriaciones a lo largo del dermatoma; pérdida irregular de la percepción táctil y zonas de dolor provocadas por un cepillado leve. Paracetamol sin mejoría.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g13-c2": {"v": "Masculino de 67 años sin enfermedades conocidas, con 18 meses de dolor insidioso, bilateral, en pies hasta 15 cm por arriba del tobillo, EVA 6/10, urente, constante, peor por la noche, con parestesias, disestesias, hiperalgesia y pérdida del equilibrio. TA 160/100. Sin lesiones cutáneas; pérdida de tacto fino, grueso y vibración en los 2/3 distales y ortejos de ambos pies.", "ap": "Noviembre 2025, Ordinario 01 nov 2024 (revisión), Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g13-c3": {"v": "Masculino de 77 años con DM, HTA, cáncer renal (nefrectomía) y cáncer de próstata etapa IV. Dolor lumbar de 2 meses, 10/10, constante, de predominio nocturno, que no cede con tramadol/paracetamol ni ketorolaco. Dolor facetario L4-S1 irradiado a glúteo e ingle.", "ap": "Mayo 2023, Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g13-c4": {"v": "Femenina de 72 años con cáncer de mama tratado (cirugía y quimioterapia), sin actividad tumoral desde hace 3 meses, con dolor de espalda por metástasis vertebral T11-T12, EVA 7/10. Toma buprenorfina y dexketoprofeno. Tiene insomnio y síntomas depresivos.", "ap": "Ene-Jun 2024 (revisión), Ago-Dic 2022 (nov 2022 + lectura de examen)"}, "g13-c5": {"v": "Masculino de 72-74 años sin antecedentes, con dolor frontal y temporal derecho opresivo de 3 semanas, sin irradiación, que no cede con paracetamol ni tramadol, EVA 8/10, más intenso por las tardes; sin desencadenantes, agravantes ni acompañantes. La esposa refiere que sale de casa y dice que se quiere morir. Sin fiebre, rinorrea, tos ni acúfenos; exploración neurológica normal.", "ap": "Ago-Dic 2022 (nov 2022 + lectura de examen), Recopilación por temas (sin fecha, ≈2021), Agosto 2016 (recuerdos)"}, "g13-c6": {"v": "Femenina con cáncer de mama con metástasis en columna; tomaba paracetamol y tramadol y además presentaba insomnio.", "ap": "Recopilación por temas (sin fecha, ≈2021), 2017 (recuerdos, incl. junio 2017), Agosto 2016 (recuerdos)"}, "g13-c7": {"v": "Paciente con dolor ardoroso EVA 7/10 con salvas de 9/10 irradiado a hipogastrio, con lisis vertebral T11-T12. Desde hace 1 mes toma pregabalina 75 mg c/12 h y parches de buprenorfina 5 mg/semana; ahora EVA 4/10. Hiporexia e insomnio por el dolor. MMSE 24, GDS 14, Katz 3, Lawton 3.", "ap": "Ene-Jun 2020 (incl. versión COVID «-1»)"}, "g14-c1": {"v": "Paciente encamado que se iba de lado al sentarse en la cama y podía mantenerse de pie con ayuda (caso recordado de forma incompleta).", "ap": "Recopilación por temas (sin fecha, ≈2021)"}}};
